# Status fields restricting actions (#234), by what they do: a list of
# action tags or action names each, and beside each a `<field>_unless`
# expression (self = the bearer; actor, action_name, action_tags, target,
# status_name bound) that lifts only that list while true. A status
# instance holding one of these keys replaces its definition's value.
# Innate or equipment restrictions are a permanent status (a construct's
# `no_rest`), so these live on statuses alone.
ACTION_FORBID_FIELDS = ("forbids_actions_with_tag", "forbids_actions_with_name")
ACTION_IMMUNE_FIELDS = ("immune_to_actions_with_tag",
                        "immune_to_actions_with_name")
ACTION_RESTRICTION_FIELDS = ACTION_FORBID_FIELDS + ACTION_IMMUNE_FIELDS
UNLESS_SUFFIX = "_unless"

# Per-level status data (#259): a status definition's `levels` dict holds
# entries keyed by a level spec, exact (`3`) or from a level up (`3+`).
# Read LIVE (user call, "for now"): wherever a status field is read, the
# definition's fields come first, then each matching `N+` entry in
# ascending N, then the exact entry, a later layer's key replacing an
# earlier one's (dicts merge key by key, lists replace whole), and an
# instance's own key wins over all of them. Entries can't set the fields
# that decide how a status arrives or what kind it is.
# Status resistance (#232): a `status_resist` record's ops, the roundings
# and what a status lets resistance change (its `resist_affects`).
RESIST_OPS = ("sub", "mul", "div")
RESIST_ROUNDINGS = ("floor", "ceil", "round")
RESIST_AFFECTS = ("level", "duration", "both")


def resist_records(val: Any) -> Tuple[List[Dict[str, Any]], List[str]]:
    """The records a `status_resist` entry holds: a number is flat (`sub`,
    negative = a flat weakness), a dict `{op, value, priority}` one record,
    a list several. Returns (records, why each unusable one was left out)."""
    out: List[Dict[str, Any]] = []
    bad: List[str] = []
    items = val if isinstance(val, list) else [val]
    for it in items:
        if isinstance(it, bool):
            bad.append(f"{it!r} isn't a number or a record")
            continue
        if isinstance(it, (int, float)):
            if math.isfinite(it):
                out.append({"op": "sub", "value": it, "priority": 0})
            else:
                bad.append(f"{it!r} isn't finite")
            continue
        if not isinstance(it, dict):
            bad.append(f"{it!r} isn't a number or a record")
            continue
        op = it.get("op", "sub")
        v = it.get("value")
        pr = it.get("priority", 0)
        if op not in RESIST_OPS:
            bad.append(f"op {op!r} isn't one of {', '.join(RESIST_OPS)}")
        elif isinstance(v, bool) or not isinstance(v, (int, float)) \
                or not math.isfinite(v):
            bad.append(f"value {v!r} isn't a finite number")
        elif op in ("mul", "div") and v <= 0:
            bad.append(f"a {op} value must be above 0, got {v!r}")
        elif isinstance(pr, bool) or not isinstance(pr, (int, float)) \
                or not math.isfinite(pr):
            bad.append(f"priority {pr!r} isn't a finite number")
        else:
            out.append({"op": op, "value": v, "priority": pr})
    return out, bad


def _grant_tokens(val: Any) -> List[str]:
    """The tokens a status_immune value names (a list or a CSV text)."""
    if isinstance(val, list):
        return [str(t).strip() for t in val if str(t).strip()]
    if isinstance(val, str):
        return [t.strip() for t in val.split(",") if t.strip()]
    return []


def check_status_self_grant(sname: str, path: str, value: Any) -> None:
    """Refuse writing, at `path` of status `sname`'s data (an instance, its
    definition's data or a level entry), resistance or immunity to `sname`
    itself named outright (#232, user call). A `tag:` token that happens to
    match it is skipped when resistance is read, with a warning."""
    parts = str(path).split(".")
    if parts[0] not in ("status_resist", "status_immune"):
        return
    node: Any = value
    for k in reversed(parts[1:]):
        node = {k: node}
    if parts[0] == "status_resist":
        names = [str(k) for k in node] if isinstance(node, dict) else []
    else:
        names = _grant_tokens(node)
    if sname in names:
        what = ("resistance" if parts[0] == "status_resist" else "immunity")
        raise VTTError(f"`{sname}` can't grant {what} to itself.")


# Status layers (the layered stack mode): an instance holding applications of
# several levels keeps them as [[level, duration], ...] under this key,
# highest level first, only while there are two or more. Each layer is one
# no other layer dominates (higher or equal level AND at least as long),
# so levels fall and durations rise along the list; the instance's own
# `level` is the first layer's, its `duration` the last (longest) one's
# (None = permanent). A countdown on `duration` ticks every layer; any
# other write of the level or duration collapses the layers to the values
# written (Match._cap_live_status).
STATUS_LAYERS_KEY = "__layers"


def _layer_len(d: Any) -> float:
    return float("inf") if d is None else float(d)


def status_layer_front(layers: List[List[Any]]) -> List[List[Any]]:
    """The layers no other layer dominates, highest level first: per level
    its longest duration, and a lower level only when it outlasts every
    higher one."""
    best: Dict[Any, Any] = {}
    for lv, du in layers:
        if lv not in best or _layer_len(du) > _layer_len(best[lv]):
            best[lv] = du
    out: List[List[Any]] = []
    for lv in sorted(best, reverse=True):
        du = best[lv]
        if not out or _layer_len(du) > _layer_len(out[-1][1]):
            out.append([lv, du])
    return out


def status_layers_of(inst: Any) -> Optional[List[List[Any]]]:
    """The stored layers of a status instance, or None when it holds one
    (or a malformed value)."""
    raw = inst.get(STATUS_LAYERS_KEY) if isinstance(inst, dict) else None
    if not isinstance(raw, list) or len(raw) < 2:
        return None
    out = []
    for r in raw:
        if not (isinstance(r, list) and len(r) == 2
                and isinstance(r[0], (int, float))
                and not isinstance(r[0], bool)
                and (r[1] is None or (isinstance(r[1], (int, float))
                                      and not isinstance(r[1], bool)))):
            return None
        out.append([r[0], r[1]])
    return out


def write_status_layers(inst: Dict[str, Any],
                        layers: List[List[Any]]) -> None:
    """Store `layers` (already a front, highest level first) on `inst`:
    its level and duration from them, the list itself only for two or
    more."""
    inst["level"] = layers[0][0]
    if layers[-1][1] is None:
        inst.pop("duration", None)
    else:
        inst["duration"] = layers[-1][1]
    if len(layers) > 1:
        inst[STATUS_LAYERS_KEY] = [list(x) for x in layers]
    else:
        inst.pop(STATUS_LAYERS_KEY, None)


def settle_status_layers(inst: Any, cap: Callable[[Any], Any]) -> None:
    """Keep `inst`'s layers true to it: each layer's level held by `cap`
    (max_level), the list rebuilt as a front, and dropped (collapsed to the
    instance's own level and duration) when a write changed either."""
    layers = status_layers_of(inst)
    if layers is None:
        if isinstance(inst, dict):
            inst.pop(STATUS_LAYERS_KEY, None)
        return
    front = status_layer_front([[cap(lv), du] for lv, du in layers])
    lv, du = inst.get("level"), inst.get("duration")
    if not same_value(lv, front[0][0]) or not same_value(du, front[-1][1]):
        inst.pop(STATUS_LAYERS_KEY, None)
        return
    write_status_layers(inst, front)


STATUS_LEVELS_FIELD = "levels"
STATUS_LEVEL_EXCLUDED = ("stack", "max_level", "tags", "removes",
                         "blocked_by", "hooks", "data", STATUS_LEVELS_FIELD,
                         "level")
LEVEL_SPEC_RE = re.compile(r"^(0|[1-9][0-9]{0,8})(\+?)$")


def check_level_spec(spec: Any) -> str:
    """`spec` as a stored level spec (`3` or `3+`); raises VTTError."""
    text = str(spec).strip() if isinstance(spec, (str, int)) \
        and not isinstance(spec, bool) else ""
    if not LEVEL_SPEC_RE.fullmatch(text):
        raise VTTError(f"`{spec}` isn't a level: a whole number (`3`, the "
                       f"exact level) or one with `+` (`3+`, that level and "
                       f"up).")
    return text


def level_spec_matches(spec: str, level: Any) -> bool:
    """Whether level spec `spec` (`3` / `3+`) covers `level`."""
    mo = LEVEL_SPEC_RE.fullmatch(str(spec))
    if mo is None or isinstance(level, bool) \
            or not isinstance(level, (int, float)):
        return False
    n = int(mo.group(1))
    return level >= n if mo.group(2) else level == n


def matching_level_entries(sdef: Any, level: Any
                           ) -> List[Tuple[str, Dict[str, Any]]]:
    """(spec, entry) of definition `sdef`'s level entries covering
    `level`, in layering order: the `N+` ones by ascending N, then the
    exact one."""
    levels = sdef.get(STATUS_LEVELS_FIELD) if isinstance(sdef, dict) else None
    if not isinstance(levels, dict):
        return []
    hits = [(spec, entry) for spec, entry in levels.items()
            if isinstance(entry, dict) and level_spec_matches(spec, level)]
    return sorted(hits, key=lambda h: (not h[0].endswith("+"),
                                       int(h[0].rstrip("+"))))


def merge_layer(base: Dict[str, Any], layer: Dict[str, Any]) -> Dict[str, Any]:
    """`base` with `layer` on top: a key in both whose two values are dicts
    merges key by key, any other value of `layer` replaces (a list
    whole). New dicts; neither argument changes."""
    out = dict(base)
    for k, v in layer.items():
        if isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = merge_layer(out[k], v)
        else:
            out[k] = copy.deepcopy(v)
    return out

# The channel map of the running command (tier 4 of the map hierarchy):
# a function of a Match giving the map name the command's channel views
# there. Formulas resolve `map='view'` through it; None outside a command
# (a formula with no channel refuses `view`).
COMMAND_VIEW: "contextvars.ContextVar[Optional[Any]]" = (
    contextvars.ContextVar("vtt_command_view", default=None))
# The team view of the running command's channel, as a function of a Match
# (None: omniscient). Refusals that list a match's maps name only the maps
# that view may name (Match.maps_text). None outside a command.
COMMAND_POV: "contextvars.ContextVar[Optional[Any]]" = (
    contextvars.ContextVar("vtt_command_pov", default=None))
# Set while saved units are read back (a match file, an undo snapshot, a
# save, a corpse revived): an id that names a formula binding (`target`,
# `rider`, ...) is refused only where a unit is CREATED, so data saved
# before a binding got its name still loads (the unit stays reachable as
# entity['target']).
LEGACY_IDS_OK: "contextvars.ContextVar[bool]" = (
    contextvars.ContextVar("vtt_legacy_ids", default=False))
# How deeply movement hooks are nested right now (a hook moving a unit fires
# the next move's hooks inside itself; a transfer's arrival fires spawn
# hooks in another match), whether a limit's warning was given in this
# chain, and how many hook levels the chain has fired (a chain = one
# outermost move and everything its hooks set off). Context variables, so
# the counts span matches.
MOVE_HOOK_DEPTH: "contextvars.ContextVar[int]" = (
    contextvars.ContextVar("vtt_move_hook_depth", default=0))
MOVE_HOOK_WARNED: "contextvars.ContextVar[Optional[Set[str]]]" = (
    contextvars.ContextVar("vtt_move_hook_warned", default=None))
MOVE_HOOK_FIRED: "contextvars.ContextVar[Optional[List[int]]]" = (
    contextvars.ContextVar("vtt_move_hook_fired", default=None))


def move_hook_limit(rules: Dict[str, Any]) -> int:
    try:
        return max(1, int(rules.get("move_hook_recursion_limit", 16)))
    except (TypeError, ValueError):
        return 16


def move_hook_event_limit(rules: Dict[str, Any]) -> int:
    try:
        return max(1, int(rules.get("move_hook_event_limit", 500)))
    except (TypeError, ValueError):
        return 500


def _move_hook_warning(log: List[str], match_id: str, kind: str,
                       text: str) -> None:
    """One ⚠️ per limit per chain, in the reply and on the console (the
    bot's operator sees which server and match ran into the limit)."""
    warned = MOVE_HOOK_WARNED.get()
    if warned is None or kind in warned:
        return
    warned.add(kind)
    log.append(f"⚠️ {text}")
    ws = CURRENT_WORKSPACE.get()
    where = "/".join(x for x in (getattr(ws, "guild_key", None), match_id)
                     if x)
    print(f"⚠️ [{where or '?'}] {text}")


@contextlib.contextmanager
def move_hook_level(rules: Dict[str, Any], log: List[str],
                    match_id: str = "", move: bool = False):
    """One nesting level of movement hooks: yields True to fire them, or
    False past move_hook_recursion_limit levels deep or once the chain has
    made move_hook_event_limit moves (adding one ⚠️ per chain to `log` and
    the console). `move`: the level of a completed move's on_entity_moved
    (fire_entity_moved), which counts that move."""
    depth = MOVE_HOOK_DEPTH.get()
    fired = MOVE_HOOK_FIRED.get() if depth > 0 else None
    if depth >= move_hook_limit(rules):
        _move_hook_warning(
            log, match_id, "depth",
            f"Movement hooks nested past move_hook_recursion_limit "
            f"({move_hook_limit(rules)}): a hook keeps moving units; the "
            f"deeper moves fired no hooks.")
        yield False
        return
    if fired is not None and fired[0] >= move_hook_event_limit(rules):
        _move_hook_warning(
            log, match_id, "count",
            f"Movement hooks made {fired[0]} moves from one move, "
            f"move_hook_event_limit ({move_hook_event_limit(rules)}): hooks "
            f"that move units several times each multiply; the later moves "
            f"of this chain fired no hooks.")
        yield False
        return
    token = MOVE_HOOK_DEPTH.set(depth + 1)
    if fired is None:
        # A chain starts here (or under a transfer's hop, which nests
        # without a level of its own).
        fired = [0]
        fired_token = MOVE_HOOK_FIRED.set(fired)
        warned = MOVE_HOOK_WARNED.set(set())
    else:
        fired_token = warned = None
    if move:
        fired[0] += 1
    try:
        yield True
    finally:
        MOVE_HOOK_DEPTH.reset(token)
        if warned is not None:
            MOVE_HOOK_WARNED.reset(warned)
            MOVE_HOOK_FIRED.reset(fired_token)


def _bounded_move_hooks(fn):
    """Decorator for the Match methods that fire movement hooks: past
    move_hook_recursion_limit nested levels they fire nothing (one ⚠️ per
    chain), so a hook that moves its unit again stops."""
    import functools

    @functools.wraps(fn)
    def wrapper(self, *a, **k):
        log: List[str] = []
        with move_hook_level(self.rules, log, self.id) as ok:
            if ok:
                return fn(self, *a, **k)
        return log
    return wrapper

# A line about one unit (a death, a revive) is prefixed with this tag —
# UNIT_LINE_TAG + "<match>|<unit>|<x>|<y>|<map>" + UNIT_LINE_TAG — so the command
# layer, which knows the channel's view, can drop it where that view can't
# see the unit (vtt_commands._filter_unit_lines) and strips it everywhere.
UNIT_LINE_TAG = "\u2063"
UNIT_LINE_RE = re.compile("\u2063([^|\u2063]*)\\|([^|\u2063]*)\\|(-?\\d+)\\|(-?\\d+)\\|([^|\u2063]*)\u2063")

# say() lines (#215) carry more markers, each read and stripped by the same
# reply filter:
#   UNIT_LINE_TAG "#<match>|<unit>|<name>" UNIT_LINE_TAG   a unit's name, as
#       each channel's view sees the unit (a disguise's name to a view it
#       fools, say_hidden_unit_name to one that can't see it); <name> is the
#       name when the line was made, for a unit gone since.
#   UNIT_LINE_TAG "@<team>" UNIT_LINE_TAG   a say_to() line: shown only to
#       that team's view, and to a host in a channel without a team view.
#   SAY_OPEN_MARK   a line no view drops (`about=None`).
SAY_NAME_RE = re.compile("\u2063#([^|\u2063]*)\\|([^|\u2063]*)\\|([^\u2063]*)\u2063")
SAY_TEAM_RE = re.compile("\u2063@([^\u2063]*)\u2063")
SAY_OPEN_MARK = "\u2063!\u2063"
# How many say(private=True) lines a match keeps waiting for a host (the
# oldest go first).
HELD_SAY_MAX = 200

# Whether the running command's caller is a host (or an administrator) in a
# channel without a team view (#215): its say(private=True) lines show in the
# reply; otherwise they wait in Match.held_says. Set per command by
# CommandRegistry._run.
SAY_HOST_VIEW: "contextvars.ContextVar[bool]" = contextvars.ContextVar(
    "vtt_say_host_view", default=False)


def line_has_tag(line: str) -> bool:
    """Whether a reply line already says who may read it: a unit tag, a
    say_to() team marker or the open mark."""
    return bool(UNIT_LINE_RE.search(line) or SAY_TEAM_RE.search(line)
                or SAY_OPEN_MARK in line)


def say_plain_text(text: str) -> str:
    """A say() line with every marker gone and each unit named as it was
    when the line was made (the event log's text)."""
    text = SAY_NAME_RE.sub(lambda mo: mo.group(3), text)
    text = SAY_TEAM_RE.sub("", text).replace(SAY_OPEN_MARK, "")
    return UNIT_LINE_RE.sub("", text)


# While the engine runs something on behalf of one unit outside a command
# that names it (a zone grant settling on it, a watcher it holds or one read
# for it), the unit tag (Match.unit_tag) surface_log puts on what it shows,
# so a channel whose view can't see that unit drops the lines (V14).
SURFACE_UNIT_TAG: "contextvars.ContextVar[str]" = contextvars.ContextVar(
    "vtt_surface_unit_tag", default="")

# The ids of the matches a command reached (MatchManager.get, copy_entity,
# vtt_commands.require_target_host), collected while `!simulate` runs, so a
# run restores only those (X16). None = not collecting.
MATCHES_TOUCHED: "contextvars.ContextVar[Optional[Set[str]]]" = (
    contextvars.ContextVar("vtt_matches_touched", default=None))


def touch_match(mid: Optional[str]) -> None:
    """Note that the running command reached match `mid` (MATCHES_TOUCHED)."""
    seen = MATCHES_TOUCHED.get()
    if seen is not None and mid:
        seen.add(mid)


# Set while the engine writes the derived size vars (size_text_var /
# size_total_var, #242), which refuse every other write.
# How often one derivation re-reads a body whose var hooks keep changing
# its size inputs, and how many unsized parts the `sum` warning names.
SIZE_SYNC_PASSES = 8
SIZE_WARN_NAMES = 10
SIZE_DERIVING: "contextvars.ContextVar[bool]" = contextvars.ContextVar(
    "vtt_size_deriving", default=False)


@contextlib.contextmanager
def _outside_derivation():
    """Run the hooks an engine write or spawn fires as ordinary code, out of
    the scopes the engine set for its own write: SIZE_DERIVING (a hook's
    writes are tracked for partial templates, refused on the derived vars
    and re-derive, S15), TEMPLATE_TRACK_OFF (a resync's hooks' writes are
    tracked, S17) and PLACEMENT_IGNORE (a stamped rider's spawn hooks can't
    place a unit on its vehicle's cell, S17)."""
    if not (SIZE_DERIVING.get() or TEMPLATE_TRACK_OFF.get()
            or PLACEMENT_IGNORE.get()):
        yield
        return
    t1 = SIZE_DERIVING.set(False)
    t2 = TEMPLATE_TRACK_OFF.set(False)
    t3 = PLACEMENT_IGNORE.set(())
    try:
        yield
    finally:
        PLACEMENT_IGNORE.reset(t3)
        TEMPLATE_TRACK_OFF.reset(t2)
        SIZE_DERIVING.reset(t1)

# The workspace (MatchManager) whose command is running: formulas reach the
# server's saved entity templates through it (summon_template). Set by each
# CommandRegistry.run; None outside a command.
CURRENT_WORKSPACE: "contextvars.ContextVar[Optional[Any]]" = (
    contextvars.ContextVar("vtt_current_workspace", default=None))

# Unit ids a placement check also ignores for occupancy: a prefab stamp
# spawns a rider onto its vehicle's cells (prefab.stamp_prefab), so the
# vehicle mustn't read as standing in its way. Empty outside one.
PLACEMENT_IGNORE: "contextvars.ContextVar[Tuple[str, ...]]" = (
    contextvars.ContextVar("vtt_placement_ignore", default=()))

# Discord-role capabilities (#190): what a server's administrators let the
# members of a role do beyond a player's reach. A fixed set (user call, "for
# now"); MatchManager.role_perms maps each to role ids (`!server perms`). A
# server administrator holds every one; the CLI / GUI operator is one.
CAPABILITIES: Dict[str, str] = {
    "systems": "edit the game systems and their defaults (`!system` edits, "
               "`!defvar`, `!defpassive`, `!gclamp`, `!log format`)",
    "templates": "save, import, edit and delete entity and partial "
                 "templates, other people's included",
    "prefabs": "save, import, edit and delete prefabs, other people's "
               "included",
    "host": "create matches (`!match new`, `!match clone`); once a role "
            "holds it, only its members and administrators can",
    "gm": "act as a host of every match on the server (not as its owner: "
          "deleting it, `!host add` and the like stay the owner's)",
    "files": "read and write the server's saves folder (`!store save`, "
             "`!run`, `!history export / import`, `!match replay`, `!match "
             "journal export`)",
    "server": "`!server wipe`, `!server backups`, `!server recover`, "
              "`!store load` (it replaces every match and system)",
}
# The capabilities an action body's cmd() lines keep (action._BufferCtx):
# per-match authority, like a host's identity. The server-wide ones stay
# out, as the administrator flag does.
MATCH_CAPABILITIES = frozenset({"templates", "prefabs", "host", "gm"})


def caller_capabilities(ctx: Any) -> "frozenset[str]":
    """The capabilities of a command's caller: all of them for a server
    administrator (or a single-operator surface), a fixed set when the
    context carries one (a held command, a journal replay, an action's
    cmd() lines), else those its roles hold on the running workspace."""
    if getattr(ctx, "auto_approve", False) or getattr(ctx, "is_admin", False):
        return frozenset(CAPABILITIES)
    fixed = getattr(ctx, "capabilities", None)
    if fixed is not None:
        return frozenset(c for c in fixed if c in CAPABILITIES)
    # Outside a command (a Discord button) the surface's own workspace.
    mgr = CURRENT_WORKSPACE.get() or getattr(ctx, "_mgr", None)
    perms = getattr(mgr, "role_perms", None) or {}
    roles = {str(r) for r in (getattr(ctx, "role_ids", None) or ())}
    if not roles or not perms:
        return frozenset()
    return frozenset(c for c, ids in perms.items()
                     if c in CAPABILITIES and roles.intersection(ids))


def check_role_perms(raw: Any) -> Dict[str, List[str]]:
    """A saved role_perms map, cleaned: known capabilities only, each a
    sorted list of distinct role ids (text)."""
    out: Dict[str, List[str]] = {}
    if not isinstance(raw, dict):
        return out
    for cap, ids in raw.items():
        if cap not in CAPABILITIES or not isinstance(ids, list):
            continue
        clean = sorted({str(i) for i in ids if isinstance(i, (str, int))
                        and not isinstance(i, bool) and str(i)})
        if clean:
            out[cap] = clean
    return out


# Partial templates resolved during the running command, by (server, match
# id, pinning, name). The library can't change mid-command except through a
# template command, which clears it (invalidate_partial_cache). Set by each
# CommandRegistry.run; None outside a command (no caching).
PARTIAL_CACHE: "contextvars.ContextVar[Optional[Dict[Any, Any]]]" = (
    contextvars.ContextVar("vtt_partial_cache", default=None))


# Set while the engine rebuilds a container (resync), so its own writes
# aren't recorded as deviations.
TEMPLATE_TRACK_OFF: "contextvars.ContextVar[bool]" = (
    contextvars.ContextVar("vtt_template_track_off", default=False))


# The node budget of the materialization in progress ([left, limit]), set by
# Match._materialize_budget: references nested inside references multiply,
# so a few small partials could otherwise expand into millions of values.
_MATERIALIZE_BUDGET: "contextvars.ContextVar[Optional[List[int]]]" = (
    contextvars.ContextVar("vtt_materialize_budget", default=None))


# Set while a unit is captured for the server library (a template save): a
# reference is kept only to a partial the LIBRARY holds; one known only from
# this match's pins is written out in full, as a missing one is.
_SAVING_TO_LIBRARY: "contextvars.ContextVar[bool]" = (
    contextvars.ContextVar("vtt_saving_to_library", default=False))


def _cells_to_runs(cells: Any) -> List[List[int]]:
    """A set of (x, y) cells as row runs [y, x_from, x_to], by y then x: a
    team's fog memory or a reveal can cover a whole 500x500 map, and as one
    [x, y] pair per cell it cost ~0.6 s to write on every undo snapshot and
    disk commit."""
    rows: Dict[int, List[int]] = {}
    for x, y in cells:
        rows.setdefault(y, []).append(x)
    out: List[List[int]] = []
    for y in sorted(rows):
        xs = sorted(rows[y])
        start = prev = xs[0]
        for x in xs[1:]:
            if x != prev + 1:
                out.append([y, start, prev])
                start = x
            prev = x
        out.append([y, start, prev])
    return out


def _runs_to_cells(runs: Any, width: int, height: int) -> "set":
    """_cells_to_runs read back, clipped to a width x height grid (a run
    can't make a file load build cells past the map)."""
    out = set()
    for r in runs if isinstance(runs, list) else []:
        if (isinstance(r, (list, tuple)) and len(r) == 3
                and all(isinstance(v, int) and not isinstance(v, bool)
                        for v in r) and 1 <= r[0] <= height):
            out.update((x, r[0]) for x in range(max(1, r[1]),
                                                min(width, r[2]) + 1))
    return out


def invalidate_partial_cache() -> None:
    cache = PARTIAL_CACHE.get()
    if cache is not None:
        cache.clear()

