# Data Models
# -------------------------

# -------------------------
# Types & helpers
# -------------------------
# Directions cover the full 8-way set. Whether diagonals are actually
# usable for movement or facing is gated by per-system rules
# (allow_diagonal_movement, allow_diagonal_facing), checked at the
# command/move layer. The constant sets below are engine-wide and
# don't change with system settings.
Direction = Literal[
    "up", "down", "left", "right",
    "up_left", "up_right", "down_left", "down_right",
]
CARDINAL_DIRECTIONS: Set[str] = {"up", "down", "left", "right"}
DIAGONAL_DIRECTIONS: Set[str] = {"up_left", "up_right", "down_left", "down_right"}
ALLOWED_DIRECTIONS: Set[str] = CARDINAL_DIRECTIONS | DIAGONAL_DIRECTIONS

# Per-step deltas. y grows downward (1-based grid; (1,1) is the top-left).
DIRECTION_VECTORS: Dict[str, Tuple[int, int]] = {
    "up":         ( 0, -1),
    "down":       ( 0,  1),
    "left":       (-1,  0),
    "right":      ( 1,  0),
    "up_left":    (-1, -1),
    "up_right":   ( 1, -1),
    "down_left":  (-1,  1),
    "down_right": ( 1,  1),
}

# Reverse of DIRECTION_VECTORS: a unit (dx, dy) step maps back to its
# canonical direction name. Used by point-directed movement (pull_entity)
# that recomputes a heading each step rather than walking a fixed
# direction like push_entity does.
_VECTOR_TO_DIRECTION: Dict[Tuple[int, int], str] = {
    vec: name for name, vec in DIRECTION_VECTORS.items()
}

# Clockwise rotation orders. The 4-way variant is used when
# allow_diagonal_facing is off; the 8-way when it's on. Both start at "up".
DIRECTION_CW_ORDER_4: Tuple[str, ...] = ("up", "right", "down", "left")
DIRECTION_CW_ORDER_8: Tuple[str, ...] = (
    "up", "up_right", "right", "down_right",
    "down", "down_left", "left", "up_left",
)

# Single-cell ASCII glyphs for ASCII map rendering. Diagonals use the
# slash whose line matches the diagonal axis: '\' for the NW-SE pair
# (up_left, down_right) and '/' for the NE-SW pair (up_right, down_left).
# That means the two glyphs in each pair are AMBIGUOUS — you can't tell
# from the map alone whether a '\' is facing NW or SE. The exact facing
# is always visible via !ent dump / !ent info. We use ASCII here rather
# than the prettier unicode arrows (↖↗↘↙) because those four glyphs
# aren't in CP437 and don't render in the default Windows terminal font.
# The cardinal pair (^ v < >) is unambiguous and matches the historical
# pre-diagonal symbol set.
DIRECTION_ARROWS: Dict[str, str] = {
    "up":         "^",
    "down":       "v",
    "left":       "<",
    "right":      ">",
    "up_left":    "\\",
    "up_right":   "/",
    "down_left":  "/",
    "down_right": "\\",
}

# Facing name -> forward (dx, dy) in grid coords (x right, y down). Used to
# project footprint cells into a part's facing-relative region (front/back/
# left/right + corners). Diagonals are unnormalized (sign-only is what the
# projection needs). Keys match DIRECTION_ARROWS / ALLOWED_DIRECTIONS.
FACING_VECTORS: Dict[str, Tuple[int, int]] = {
    "up": (0, -1), "down": (0, 1), "left": (-1, 0), "right": (1, 0),
    "up_left": (-1, -1), "up_right": (1, -1),
    "down_left": (-1, 1), "down_right": (1, 1),
}

# Named text colors -> ANSI SGR foreground codes, for the colorized text
# renderer (Discord ```ansi blocks + ANSI terminals). The names are the
# only valid values for an entity `color` var / a team color; an unknown
# name renders uncolored. Foreground only for now.
#
# Codes are chosen to work on BOTH a real ANSI terminal AND Discord's
# ```ansi blocks. Discord supports only the 30-37 foreground set plus
# style 1 (bold) — it does NOT understand the 90-97 "bright" range — so the
# bright variants are expressed as bold + base color (`1;3X`), which renders
# bright on Discord and (bold/bright) on a terminal. Plain `gray` is bold
# black, the brightest Discord gets toward grey.
TEXT_COLORS: Dict[str, str] = {
    "black": "30", "red": "31", "green": "32", "yellow": "33",
    "blue": "34", "magenta": "35", "cyan": "36", "white": "37",
    "gray": "1;30", "grey": "1;30",
    "bright_red": "1;31", "bright_green": "1;32", "bright_yellow": "1;33",
    "bright_blue": "1;34", "bright_magenta": "1;35", "bright_cyan": "1;36",
    "bright_white": "1;37",
}

# !map resize anchors: name (+ aliases) -> (horizontal, vertical) kind.
# horizontal in {left, center, right}; vertical in {top, middle, bottom}.
# The anchor names the corner/edge where existing content stays put; the
# shift offset is derived from it (left/top = 0, right/bottom = full delta,
# center/middle = half). See Match.resize_grid.
_RESIZE_ANCHORS: Dict[str, Tuple[str, str]] = {
    "top-left": ("left", "top"), "tl": ("left", "top"),
    "topleft": ("left", "top"),
    "top": ("center", "top"), "top-center": ("center", "top"),
    "tc": ("center", "top"), "t": ("center", "top"),
    "top-right": ("right", "top"), "tr": ("right", "top"),
    "topright": ("right", "top"),
    "left": ("left", "middle"), "l": ("left", "middle"),
    "center-left": ("left", "middle"), "cl": ("left", "middle"),
    "center": ("center", "middle"), "c": ("center", "middle"),
    "middle": ("center", "middle"), "m": ("center", "middle"),
    "right": ("right", "middle"), "r": ("right", "middle"),
    "center-right": ("right", "middle"), "cr": ("right", "middle"),
    "bottom-left": ("left", "bottom"), "bl": ("left", "bottom"),
    "bottomleft": ("left", "bottom"),
    "bottom": ("center", "bottom"), "bottom-center": ("center", "bottom"),
    "bc": ("center", "bottom"), "b": ("center", "bottom"),
    "bottom-right": ("right", "bottom"), "br": ("right", "bottom"),
    "bottomright": ("right", "bottom"),
}

# Maps every accepted alias to the canonical direction name. The parser
# also strips hyphens and lowercases before lookup, so "Up-Left" matches
# "up_left" without needing a separate entry.
_DIRECTION_ALIASES: Dict[str, str] = {
    # Cardinals
    "up": "up", "u": "up", "north": "up", "n": "up",
    "down": "down", "d": "down", "south": "down", "s": "down",
    "left": "left", "l": "left", "west": "left", "w": "left",
    "right": "right", "r": "right", "east": "right", "e": "right",
    # Diagonals — canonical underscore form, separator-free, two-letter,
    # and the four compass abbreviations.
    "up_left": "up_left", "upleft": "up_left", "ul": "up_left",
    "northwest": "up_left", "north_west": "up_left", "nw": "up_left",
    "up_right": "up_right", "upright": "up_right", "ur": "up_right",
    "northeast": "up_right", "north_east": "up_right", "ne": "up_right",
    "down_left": "down_left", "downleft": "down_left", "dl": "down_left",
    "southwest": "down_left", "south_west": "down_left", "sw": "down_left",
    "down_right": "down_right", "downright": "down_right", "dr": "down_right",
    "southeast": "down_right", "south_east": "down_right", "se": "down_right",
}


def normalize_direction(token: str) -> Optional[str]:
    """Map any user-provided direction alias to its canonical name.

    Accepts cardinals (up/down/left/right + u/d/l/r + n/s/e/w + compass
    names), diagonals (up_left/up-left/upleft/ul/nw and so on), and is
    case-insensitive. Returns None for unrecognized input — callers
    typically raise VTTError with their own message in that case.

    Does NOT check whether the canonical direction is permitted by the
    current game system; that's the caller's job (see Entity.move_dirs
    and the !ent face command for the allow_diagonal_* rule gating).
    """
    if not isinstance(token, str):
        return None
    t = token.strip().lower().replace("-", "_")
    return _DIRECTION_ALIASES.get(t)


def rotate_direction(facing: str, *, clockwise: bool, eight_way: bool) -> str:
    """Return the next direction one rotation step from `facing`.

    eight_way=True  rotates through all 8 directions (cardinals + diagonals).
    eight_way=False rotates only through the 4 cardinals.

    If `facing` is a diagonal but eight_way is False (e.g. the system was
    flipped after an entity was already facing diagonally), we snap to
    the nearest cardinal in the rotation direction in a single step,
    rather than spinning through diagonals the system has just disallowed.
    Unknown facings degrade to "up".
    """
    order = DIRECTION_CW_ORDER_8 if eight_way else DIRECTION_CW_ORDER_4
    if facing not in order:
        # Off-axis: snap to the nearest in `order` along the rotation
        # direction. We walk the full 8-way ring one step at a time and
        # return the first entry that lives in our reduced order.
        full = DIRECTION_CW_ORDER_8
        if facing not in full:
            return order[0]
        idx_full = full.index(facing)
        step = 1 if clockwise else -1
        for off in range(1, len(full) + 1):
            cand = full[(idx_full + off * step) % len(full)]
            if cand in order:
                return cand
        return order[0]
    idx = order.index(facing)
    step = 1 if clockwise else -1
    return order[(idx + step) % len(order)]


# ---- Event log (combat log) --------------------------------------------------
# The engine appends structured event records to Match.event_log at its
# chokepoints. Each record is a dict {type, round, turn, ...fields}; the
# text shown by !log is produced at READ time from a per-type template,
# so the stored data stays un-opinionated. EVENT_LOG_AUTO_TYPES are the
# engine-emitted types (custom is reserved for the log() primitive). Each
# is gated by the event_log_enabled master switch AND membership in the
# event_log_events rule. The default templates below are overridable per
# type via the event_log_format rule (a dict, edited with `!log format`).
EVENT_LOG_AUTO_TYPES: Tuple[str, ...] = (
    "death", "revive", "spawn", "move",
    "damage", "heal", "status_added", "status_removed",
    "action_used", "action_failed", "say",
)

# Built-in render templates, keyed by event type. Same placeholder syntax
# as entity_line_format ({key}, {?key?}...{/?}, dotted paths, \n). The
# fields available per type are whatever Match.log_event stores for it
# (see each call site). A type with no override and no entry here renders
# as a compact key=value dump (see the !log command).
EVENT_LOG_DEFAULT_FORMATS: Dict[str, str] = {
    "death":          "💀 {name} (`{entity}`) died at ({x},{y}).",
    "revive":         "✨ {name} (`{entity}`) was revived.",
    "spawn":          "➕ {name} (`{entity}`) spawned at ({x},{y}).",
    "move":           "👣 {name} (`{entity}`) moved ({from_x},{from_y})→({to_x},{to_y}).",
    "damage":         "🩸 {name} (`{entity}`) took {amount} damage ({var} {old}→{new}).",
    "heal":           "💚 {name} (`{entity}`) healed {amount} ({var} {old}→{new}).",
    "status_added":   "🔆 {name} (`{entity}`) gained status `{status}`.",
    "status_removed": "🔅 {name} (`{entity}`) lost status `{status}`.",
    "action_used":    "⚔️ {actor_name} (`{actor}`) used `{action}`{?target?} → {target}{/?}.",
    "action_failed":  "✖️ {actor_name} (`{actor}`) failed `{action}`: {message}",
    "custom":         "{message}",
    "say":            "💬 {message}",
}

# ---- Rule registry & model ---------------------------------------------------
# Each rule now has a default, schema, and description. GameSystems store
# per-system overrides as Rule objects (key/value/schema/description).
#
# Schema types: "bool", "int", "enum"
# The largest size a unit, a default or a corpse total may hold (#242, E8):
# past the float range a size crashed the reads and the default's maths.
SIZE_LIMIT = 10 ** 15

# Unit history kept in a unit's saved dict (Entity.actions_seen) that a
# NEW unit made from it must not inherit: stripped with the identity keys
# by templates, statblocks, summon snapshots, prefabs, clones and copies.
UNIT_HISTORY_KEYS: Tuple[str, ...] = ("actions_seen",)
# At most this many recorded action paths per unit and team (each distinct
# path once).
ACTIONS_USED_MAX = 1000

# The longest player-facing var label (`!system labels set`).
VAR_LABEL_MAX = 100


def var_label_problem(path: Any, label: Any) -> Optional[str]:
    """Why `path` -> `label` can't be a var label, or None: the path is a
    dotted var path (no empty segment, no `__` segment: engine keys never
    show to players), the label one line of text of at most VAR_LABEL_MAX
    characters."""
    if not isinstance(path, str) or not path:
        return "the var path is empty"
    segs = path.split(".")
    if any(not x for x in segs):
        return f"`{path}` has an empty segment"
    if any(x.startswith("__") for x in segs):
        return f"`{path}` names a `__` key, which players never see"
    if not isinstance(label, str) or not label.strip():
        return "the label is empty"
    if "\n" in label or len(label) > VAR_LABEL_MAX:
        return (f"a label is one line of at most {VAR_LABEL_MAX} "
                f"characters")
    return None


def var_label_for(labels: Dict[str, str], path: str) -> Optional[str]:
    """The label of the var at dotted `path` from `labels` (a system's
    var_labels): an entry for the whole path wins over one for its last
    key, which names that key at any depth. None = no label."""
    if path in labels:
        return labels[path]
    key = path.rsplit(".", 1)[-1]
    return labels.get(key)


# ---- private vars (#70) ------------------------------------------------
# A var is private (hosts only, outside a team-view channel) or team-private
# (hosts and the unit's own team's view) when the private_vars /
# team_private_vars rules or the unit's own lists name its path (or `*.<key>`
# its key, at any depth), or when a container on its path holds
# `__private_container`. Player-facing reads (the card, roster lines, the
# description, `!find` / `!foreach`, `$()`, Tab) read the vars through
# `redact_vars` under the command's VAR_READER; `!ent dump` and the formulas
# the engine runs read them whole.
PRIVATE_LIST_VARS: Dict[str, str] = {"private": "__private_vars",
                                     "team": "__team_private_vars"}
PRIVATE_CONTAINER_KEY = "__private_container"


@dataclass(frozen=True)
class VarReader:
    """Who reads a unit's vars in this command: `team` the channel's team
    view (None = none), `host` whether the reader hosts the match (for the
    private_var_host_reminder). A command with no reader (VAR_READER None)
    reads everything: a host or an administrator outside a team view."""
    team: Optional[str]
    host: bool = False


VAR_READER: "contextvars.ContextVar[Optional[VarReader]]" = (
    contextvars.ContextVar("vtt_var_reader", default=None))
# One top-level command's memo of which units hold anything private
# (privacy_applies), per match: a `!foreach` of `$()` reads scans each unit
# once, not once per line (X21). write_var / remove_var drop the written
# unit's entry. Set by CommandRegistry._run_top; None = no memo.
PRIVATE_SCAN: "contextvars.ContextVar[Optional[Dict[Any, Any]]]" = (
    contextvars.ContextVar("vtt_private_scan", default=None))


def private_scan_forget(match: Any, eid: str) -> None:
    """A write changed `eid`'s vars: the command's memo reads it again."""
    memo = PRIVATE_SCAN.get()
    if memo:
        for key, held in memo.items():
            if key[0] == id(match):
                held[1].pop(eid, None)


# Set while a host's command runs: noted when a read withheld a private var
# from that host (the private_var_host_reminder).
PRIVATE_WITHHELD: "contextvars.ContextVar[Optional[List[bool]]]" = (
    contextvars.ContextVar("vtt_private_withheld", default=None))


def private_entry_problem(word: Any) -> Optional[str]:
    """Why `word` can't name private vars (a var path, or `*.<key>`)."""
    if not isinstance(word, str) or not word:
        return "empty"
    path = word[2:] if word.startswith("*.") else word
    if not path or any(not seg for seg in path.split(".")):
        return "an empty segment"
    if word.startswith("*.") and "." in path:
        return "`*.` takes one key"
    return None


def _private_words(raw: Any) -> List[str]:
    if isinstance(raw, list):
        words = [str(w).strip() for w in raw if isinstance(w, str)]
    elif isinstance(raw, str):
        words = [w for w in re.split(r"[\s,]+", raw) if w]
    else:
        return []
    return [w for w in words if w and private_entry_problem(w) is None]


def privacy_spec(rules: Dict[str, Any], *roots: Any
                 ) -> Dict[str, Tuple[set, set]]:
    """level -> (paths, keys): the rules' entries plus the per-unit lists
    held at each vars root in `roots` (a unit's vars; a disguise's decoys
    take the real unit's too)."""
    out: Dict[str, Tuple[set, set]] = {}
    for level, rule in (("private", "private_vars"),
                        ("team", "team_private_vars")):
        words = _private_words(rules.get(rule, ""))
        for root in roots:
            if isinstance(root, dict):
                words += _private_words(root.get(PRIVATE_LIST_VARS[level]))
        paths = {w for w in words if not w.startswith("*.")}
        keys = {w[2:] for w in words if w.startswith("*.")}
        if str(rules.get("private_size_display", "category")) == "show":
            # The size can't be hidden: the size number is never private.
            num = str(rules.get("size_num_var", "size_num"))
            paths.discard(num)
            keys.discard(num)
        out[level] = (paths, keys)
    return out


def _container_level(value: Any) -> Optional[str]:
    """The level a `__private_container` flag in dict `value` gives."""
    if not isinstance(value, dict) or PRIVATE_CONTAINER_KEY not in value:
        return None
    flag = value.get(PRIVATE_CONTAINER_KEY)
    if isinstance(flag, str):
        flag = flag.strip().lower()
        if flag == "team":
            return "team"
        return "private" if flag in ("yes", "true", "private", "1") else None
    return "private" if flag is True or flag == 1 else None


def _level_of(spec: Dict[str, Tuple[set, set]], path: str, key: str,
              value: Any) -> Optional[str]:
    found = None
    for level in ("private", "team"):
        paths, keys = spec.get(level, (set(), set()))
        if path in paths or key in keys:
            found = found or level
    flag = _container_level(value)
    if flag == "private" or found == "private":
        return "private"
    return found or flag


def reader_sees(level: Optional[str], reader: Optional[VarReader],
                team: Optional[str]) -> bool:
    """Whether `reader` may read a var of `level` on a unit of `team`."""
    if level is None or reader is None:
        return True
    if level == "team":
        return (reader.team is not None and team is not None
                and str(reader.team) == str(team))
    return False


def privacy_applies(spec: Dict[str, Tuple[set, set]], vars_root: Any) -> bool:
    """Whether anything in `vars_root` is private or team-private under
    `spec`: a path or `*.<key>` entry it holds, a per-unit list, or a
    `__private_container` flag (dicts inside lists included). A walk that
    copies nothing, so a unit without private vars costs a read (X21)."""
    if not isinstance(vars_root, dict):
        return False
    if any(vars_root.get(k) for k in PRIVATE_LIST_VARS.values()):
        return True
    paths = set().union(*(spec.get(lv, (set(), set()))[0]
                          for lv in ("private", "team")))
    keys = set().union(*(spec.get(lv, (set(), set()))[1]
                         for lv in ("private", "team")))
    for path in paths:
        node: Any = vars_root
        for seg in path.split("."):
            node = node.get(seg, _MISSING) if isinstance(node, dict) \
                else _MISSING
            if node is _MISSING:
                break
        else:
            return True
    stack: List[Any] = [vars_root]
    while stack:
        node = stack.pop()
        if isinstance(node, dict):
            if PRIVATE_CONTAINER_KEY in node:
                return True
            for k, v in node.items():
                if keys and str(k) in keys:
                    return True
                if isinstance(v, (dict, list)):
                    stack.append(v)
        else:
            stack.extend(v for v in node if isinstance(v, (dict, list)))
    return False


def path_privacy(spec: Dict[str, Tuple[set, set]], vars_root: Any,
                 path: str) -> Optional[str]:
    """The level that hides `path` in `vars_root` (its own entry, an
    ancestor's, or a private container on the way), or None."""
    level = None
    node = vars_root
    at = ""
    for seg in path.split("."):
        at = f"{at}.{seg}" if at else seg
        if isinstance(node, dict):
            node = node.get(seg)
        elif isinstance(node, list) and seg.isdigit() \
                and int(seg) < len(node):
            node = node[int(seg)]
        else:
            node = None
        lv = _level_of(spec, at, seg, node)
        if lv == "private":
            return "private"
        level = level or lv
    return level


def redact_vars(spec: Dict[str, Tuple[set, set]], vars_root: Dict[str, Any],
                team: Optional[str], reader: Optional[VarReader]
                ) -> Tuple[Dict[str, Any], bool]:
    """(vars `reader` may read, whether anything was left out): a copy of
    `vars_root` without the private vars it may not see, nor the per-unit
    lists naming them (their paths would tell what is hidden). `vars_root`
    itself when nothing applies (no reader)."""
    if reader is None or not privacy_applies(spec, vars_root):
        return vars_root, False
    withheld = [False]

    def walk(node: Dict[str, Any], at: str) -> Dict[str, Any]:
        out: Dict[str, Any] = {}
        for k, v in node.items():
            key = str(k)
            path = f"{at}.{key}" if at else key
            if not at and key in PRIVATE_LIST_VARS.values():
                continue
            if not reader_sees(_level_of(spec, path, key, v), reader, team):
                withheld[0] = True
                continue
            out[k] = sub(v, path)
        return out

    def sub(v: Any, path: str) -> Any:
        # A list's dicts are read like the dicts around them: a `*.<key>`
        # entry or a container flag inside one hides there too (V17); an
        # item's index is a path segment (`traps.0.dc`).
        if isinstance(v, dict):
            return walk(v, path)
        if isinstance(v, list):
            out_l: List[Any] = []
            for i, item in enumerate(v):
                ipath = f"{path}.{i}"
                if isinstance(item, dict) and not reader_sees(
                        _level_of(spec, ipath, str(i), item), reader, team):
                    withheld[0] = True
                    continue
                out_l.append(sub(item, ipath))
            return out_l
        return copy.deepcopy(v)

    red = walk(vars_root if isinstance(vars_root, dict) else {}, "")
    if withheld[0] and reader.host:
        note = PRIVATE_WITHHELD.get()
        if note is not None:
            note.append(True)
    return red, withheld[0]


def _checked_actions_seen(raw: Any) -> Dict[str, List[str]]:
    """A saved Entity.actions_seen read back: team -> distinct paths (text),
    at most ACTIONS_USED_MAX each; anything else dropped."""
    out: Dict[str, List[str]] = {}
    if isinstance(raw, dict):
        for team, paths in raw.items():
            if isinstance(paths, list):
                keep = list(dict.fromkeys(p for p in paths
                                          if isinstance(p, str)))
                if keep:
                    out[str(team)] = keep[:ACTIONS_USED_MAX]
    return out


