# Precomputed views of RULES_REGISTRY for fast lookup at call sites that
# only need the default value or the schema (not the full registry entry).
DEFAULT_SYSTEM_SETTINGS: Dict[str, Any] = {
    k: v["default"] for k, v in RULES_REGISTRY.items()
}
RULE_SCHEMA: Dict[str, Dict[str, Any]] = {
    k: v["schema"] for k, v in RULES_REGISTRY.items()
}
# A system that overrides a rule saves the rule's schema with it, so every
# schema and default must be JSON (a `set` of choices once made every save of
# the server fail after `!system set ... spawn_default_facing`).
for _rk, _rv in RULES_REGISTRY.items():
    try:
        json.dumps({"default": _rv["default"], "schema": _rv["schema"]})
    except TypeError as _ex:
        raise TypeError(f"RULES_REGISTRY[{_rk!r}] isn't JSON: {_ex}")

@dataclass
class Rule:
    key: str
    value: Any
    schema: Dict[str, Any]
    description: str


#functions to use alongside RULE_SCHEMA
def _coerce_vital_value(v: Any) -> Optional[int]:
    """Coerce a value destined for a vital var (hp/max_hp/initiative) to an
    int, or None if it isn't a valid number. bool is rejected (a True flag is
    almost certainly a mistake, not hp=1); numeric strings and floats are
    accepted (a float truncates, matching the int() the getters use)."""
    if isinstance(v, bool):
        return None
    if isinstance(v, int):
        return v
    try:
        if isinstance(v, float):
            return int(v)
        if isinstance(v, str):
            return int(float(v.strip()))
    except (ValueError, OverflowError):   # "abc", NaN, infinity
        return None
    return None


def team_text(v: Any) -> Any:
    """A team var's value as the text the engine compares: a number or bool
    becomes text (`1`, `1.0` and "1" are one team; True is "true"), None and
    "" stay (no team), text stays as written. A dict or list is refused
    (None returned). The team var is stored this way when written, so a
    formula reading `entity[u].team` sees the same value `is_hostile`,
    `team_members` and `team_get` use."""
    if v is None or isinstance(v, str):
        return v
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        if v != v or v in (float("inf"), float("-inf")):
            return str(v)
        return str(int(v)) if v.is_integer() else str(v)
    return None


def flag_value(v: Any) -> Optional[bool]:
    """A stored on / off setting: a bool, a number, or text _parse_bool
    reads; None when unset or unreadable (the caller's default applies)."""
    if v is None:
        return None
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return bool(v)
    if isinstance(v, str):
        try:
            return _parse_bool(v)
        except VTTError:
            return None
    return None


def _parse_bool(token: str) -> bool:
    """Parse a boolean from a command-line token.

    Accepts a wide variety of truthy/falsy spellings since these arrive from
    Discord and the CLI where typing conventions vary. Case-insensitive.
    Truthy: true, t, yes, y, on, 1.
    Falsy:  false, f, no, n, off, 0.
    Anything else raises VTTError.
    """
    t = token.strip().lower()
    if t in ("true", "t", "yes", "y", "on", "1"): return True
    if t in ("false", "f", "no", "n", "off", "0"): return False
    raise VTTError(
        "Expected a boolean: use 'true'/'false', 'yes'/'no', 'on'/'off', or '1'/'0'."
    )

# The bot owner's ceilings on the limit rules marked `"ceiling": True` in
# their schema (`!owner ceiling`, kept in data/bot_settings.json): rule key ->
# highest value a server may set. A rule without an entry uses its schema
# `max`. Every server shares one process, so a server must not be able to set
# a limit high enough to stall the bot for the others.
RULE_CEILINGS: Dict[str, int] = {}


def rule_max(key: str) -> Optional[int]:
    """The highest value rule `key` accepts (owner ceiling, else schema max)."""
    spec = RULES_REGISTRY.get(key, {}).get("schema", {})
    if spec.get("ceiling") and key in RULE_CEILINGS:
        return RULE_CEILINGS[key]
    return spec.get("max")


def _finite_text(t: str) -> bool:
    try:
        return math.isfinite(float(t))
    except ValueError:
        return False


def _check_stat_caps(key: str, raw: str) -> str:
    out = []
    for tok in (t.strip() for t in raw.split(",")):
        if not tok:
            continue
        parts = tok.split(":")
        if not (2 <= len(parts) <= 3) or not parts[0].strip() or any(
                p.strip() and not _finite_text(p) for p in parts[1:]):
            raise VTTError(f"Setting '{key}' takes `stat:lo:hi` entries, "
                           f"comma-separated (lo / hi numbers, either one "
                           f"blank), got `{tok}`.")
        out.append(tok)
    return ",".join(out)


def _check_op_priority(key: str, raw: str) -> str:
    out = []
    for tok in (t.strip() for t in raw.split(",")):
        if not tok:
            continue
        op, sep, num = tok.partition(":")
        if not sep or op.strip() not in MODIFIER_OPS or not _finite_text(num):
            raise VTTError(f"Setting '{key}' takes `op:number` entries for "
                           f"the ops {', '.join(MODIFIER_OPS)}, got `{tok}`.")
        out.append(f"{op.strip()}:{num.strip()}")
    return ",".join(out)


def _check_resist_op_priority(key: str, raw: str) -> str:
    out = []
    for tok in (t.strip() for t in raw.split(",")):
        if not tok:
            continue
        op, sep, num = tok.partition(":")
        if not sep or op.strip() not in RESIST_OPS or not _finite_text(num):
            raise VTTError(f"Setting '{key}' takes `op:number` entries for "
                           f"the ops {', '.join(RESIST_OPS)}, got `{tok}`.")
        out.append(f"{op.strip()}:{num.strip()}")
    return ",".join(out)


def _check_rgb_rule(key: str, raw: str) -> str:
    v = raw.strip()
    if re.fullmatch(r"#[0-9a-fA-F]{6}", v):
        return v
    parts = v.split(",")
    if len(parts) == 3 and all(p.strip().isdigit() and 0 <= int(p) <= 255
                               for p in parts):
        return ",".join(p.strip() for p in parts)
    raise VTTError(f"Setting '{key}' takes `r,g,b` (0-255 each) or "
                   f"#rrggbb, got `{raw}`.")


_PLAIN_KEY_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _check_plain_key(key: str, raw: str) -> str:
    v = raw.strip()
    if not _PLAIN_KEY_RE.fullmatch(v) or v.startswith("__"):
        raise VTTError(f"Setting '{key}' names one field: letters, digits "
                       f"and _ (no dots, not starting with __), got `{raw}`.")
    return v


def _check_var_path_rule(key: str, raw: str) -> str:
    v = raw.strip()
    if v and (any(not seg or not _PLAIN_KEY_RE.fullmatch(seg)
                  for seg in v.split(".")) or v.startswith("__")):
        raise VTTError(f"Setting '{key}' names a var path (`dex`, "
                       f"`stats.agi`): words of letters, digits and _ "
                       f"joined by dots, got `{raw}`.")
    return v


def _check_top_vars(key: str, raw: str) -> str:
    got = [w.strip() for w in raw.split(",") if w.strip()]
    bad = [w for w in got if not _PLAIN_KEY_RE.fullmatch(w)]
    if bad:
        raise VTTError(f"Setting '{key}' takes a comma list of top-level "
                       f"var names, not {', '.join(bad)}.")
    return ",".join(got)


# The rules a body's derived size reads (#242): a change of one re-derives
# every body (MatchManager.apply_system_rules).
SIZE_RULES = ("size_enabled", "size_categories", "size_default",
              "size_default_per_extra_tile", "size_total_mode",
              "size_parts_inherit", "size_decimals", "size_num_var",
              "size_text_var", "size_total_var",
              "footprint_width_var", "footprint_height_var")


_SIZE_NUMBER_RE = re.compile(r"[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?")


def size_number_ok(v: Any) -> bool:
    """Whether `v` is a size number: a finite int / float (not a bool) of
    at most SIZE_LIMIT either way (an int past the float range made
    math.isfinite raise, E8)."""
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        return False
    if isinstance(v, float) and not math.isfinite(v):
        return False
    return abs(v) <= SIZE_LIMIT


def derived_clamp_error(path: Any, var_names: Any = None) -> Optional[str]:
    """Why a clamp can't sit on `path` (None when it can): the derived size
    vars are the engine's, so a clamp bends them away from their source
    (user call, S15). `var_names` maps the size var rules to names (a
    match's rules, a template's var_names); absent ones read the
    defaults."""
    vn = var_names if isinstance(var_names, dict) else {}
    seg0 = str(path).split(".", 1)[0]
    num_v = str(vn.get("size_num_var") or "size_num")
    if seg0 in (str(vn.get("size_text_var") or "size_text"),
                str(vn.get("size_total_var") or "size_total")):
        return (f"`{seg0}`: it is derived from `{num_v}`, so clamp "
                f"`{num_v}` instead (the derived size follows it).")
    return None


def check_size_var(vars_: Any, var_names: Any, where: str) -> None:
    """Refuse a stored unit (a template, a prefab unit) whose size number
    isn't one: each spawn would refuse it (L43). A category name is the
    spawning system's, so a stored size is a number."""
    vn = var_names if isinstance(var_names, dict) else {}
    key = str(vn.get("size_num_var") or "size_num")
    if isinstance(vars_, dict) and key in vars_ \
            and not size_number_ok(vars_[key]):
        got = repr(vars_[key])
        if len(got) > 40:       # a 400-digit number echoed whole (L45)
            got = got[:20] + f"… ({len(got)} characters)"
        raise VTTError(f"{where}: `{key}` is a size number (finite, at "
                       f"most {SIZE_LIMIT} either way), got {got}.")


def _corpse_vars(corpse: Any) -> Optional[Dict[str, Any]]:
    """The vars of a corpse's unit snapshot (None when malformed)."""
    ent = corpse.get("entity") if isinstance(corpse, dict) else None
    cv = ent.get("vars") if isinstance(ent, dict) else None
    return cv if isinstance(cv, dict) else None


def _size_trigger(match: Any, path: str, unit: Any = None) -> bool:
    """Whether a write / delete at `path` can change its body's size: the
    size number, the footprint vars (an unsized unit's default), the
    per-body mode / inherit overrides, and a body part's hp (its death or
    a heal changes what a `sum` / `max` body counts, S16)."""
    if SIZE_DERIVING.get() or not match.sizes_on():
        return False
    seg0 = path.split(".", 1)[0]
    r = match.rules
    if unit is not None and unit.part_of and "." not in path \
            and path == str(r.get("hp_var", "hp")):
        return True
    return seg0 in (str(r.get("size_num_var", "size_num")),
                    str(r.get("footprint_width_var", "footprint_w")),
                    str(r.get("footprint_height_var", "footprint_h")),
                    "__size_total_mode", "__size_parts_inherit")


def parse_size_scale(text: Any) -> List[Tuple[str, Optional[float]]]:
    """`size_categories` as [(name, start)], smallest first; the first
    category's start is None (it holds everything below the second's).
    Raises VTTError on a malformed scale: a name that isn't a plain word, a
    repeated name, a start on the first category or missing on a later
    one, starts that don't rise strictly."""
    out: List[Tuple[str, Optional[float]]] = []
    raw = str(text or "").strip()
    if not raw:
        return out
    for i, tok in enumerate(t.strip() for t in raw.split(",")):
        name, colon, num = tok.partition(":")
        name = name.strip()
        if not _PLAIN_KEY_RE.fullmatch(name) or name.startswith("__"):
            raise VTTError(f"size_categories: `{tok}` isn't `name:start` "
                           f"(a name of letters, digits and _).")
        if any(n == name for n, _s in out):
            raise VTTError(f"size_categories: `{name}` is named twice.")
        if i == 0:
            if colon:
                raise VTTError(
                    f"size_categories: the first category takes no start: "
                    f"it holds every size below the second's (`{name}, "
                    f"next:<start>, ...`).")
            out.append((name, None))
            continue
        try:
            start = float(num)
        except ValueError:
            raise VTTError(f"size_categories: `{tok}` needs a number "
                           f"start (`{name}:<start>`).")
        if not colon or not math.isfinite(start):
            raise VTTError(f"size_categories: `{tok}` needs a number "
                           f"start (`{name}:<start>`).")
        prev = out[-1][1]
        if prev is not None and start <= prev:
            raise VTTError(f"size_categories: starts rise strictly, and "
                           f"`{name}:{num.strip()}` doesn't rise past "
                           f"`{out[-1][0]}`.")
        out.append((name, int(start) if start.is_integer() else start))
    return out


def _check_size_scale(key: str, raw: str) -> str:
    scale = parse_size_scale(raw)
    return ", ".join(n if s is None else f"{n}:{s}" for n, s in scale)


def _check_private_paths(key: str, raw: str) -> str:
    """A private_vars / team_private_vars list: var paths and `*.<key>`."""
    got = [w for w in re.split(r"[\s,]+", raw) if w]
    bad = [w for w in got if private_entry_problem(w)]
    if bad:
        raise VTTError(f"Setting '{key}' takes var paths (`stats.dc`) and "
                       f"`*.<key>` entries, comma-separated; not "
                       + ", ".join(f"`{b}`" for b in bad) + ".")
    return ", ".join(got)


def _check_var_path_list(key: str, raw: str) -> str:
    """A comma list of var paths and `@<var-name rule>` entries
    (transform_keep_vars)."""
    got = [w for w in re.split(r"[\s,]+", raw) if w]
    for w in got:
        if w.startswith("@"):
            if w[1:] + "_var" not in VAR_NAME_RULES:
                raise VTTError(
                    f"Setting '{key}': `{w}` names no var-name rule; an "
                    f"`@` entry is one of "
                    + ", ".join(f"`@{r[:-4]}`" for r in VAR_NAME_RULES)
                    + ".")
            continue
        _check_var_path_rule(key, w)
    return ", ".join(got)


_FORMAT_RULE_CHECKS = {
    "transform_keep_vars": _check_var_path_list,
    "private_vars": _check_private_paths,
    "team_private_vars": _check_private_paths,
    "size_categories": _check_size_scale,
    "modifier_stat_caps": _check_stat_caps,
    "modifier_op_priority": _check_op_priority,
    "status_resist_op_priority": _check_resist_op_priority,
    "preview_color": _check_rgb_rule,
    "amount_field": _check_plain_key,
    "turnorder_tiebreak_var": _check_var_path_rule,
    "action_container_paths": _check_top_vars,
}


def _coerce_rule_value(key: str, raw_value: str):
    # Unknown key? block (prevents typos or unimplemented settings).
    # When the rule schema gets large the bare "Allowed: ..." dump is
    # noise, so we put close-match suggestions FIRST (the common case
    # for unknown rules is a typo) and only show the full list if we
    # have no good guesses.
    if key not in RULE_SCHEMA:
        import difflib as _difflib
        keys = sorted(RULE_SCHEMA.keys())
        hits = _difflib.get_close_matches(key, keys, n=3, cutoff=0.55)
        if hits:
            suggestions = ", ".join(f"'{h}'" for h in hits)
            raise VTTError(
                f"Unknown setting '{key}'. Did you mean: {suggestions}? "
                f"Use `!system rules` to see all settings."
            )
        allowed = ", ".join(keys)
        raise VTTError(f"Unknown setting '{key}'. Allowed: {allowed}")

    spec = RULE_SCHEMA[key]
    t = spec["type"]

    if t == "bool":
        return _parse_bool(raw_value)

    if t == "int":
        try:
            v = int(raw_value, 10)
        except ValueError:
            raise VTTError(f"Setting '{key}' expects an integer.")
        # Bounds: a limit set to -1 (the "unlimited" of the retention rules)
        # or an opacity of 150 used to be accepted and then refuse or
        # misbehave on use. `unlimited` rules also take -1.
        lo, hi = spec.get("min"), rule_max(key)
        if spec.get("unlimited") and v == -1:
            return v
        if (lo is not None and v < lo) or (hi is not None and v > hi):
            if hi is None:
                rng = f"at least {lo}"
            elif lo is None:
                rng = f"at most {hi}"
            else:
                rng = f"between {lo} and {hi}"
            extra = " (or -1 for unlimited)" if spec.get("unlimited") else ""
            if spec.get("ceiling") and hi is not None and v > hi:
                extra += " — the bot owner's ceiling"
            raise VTTError(f"Setting '{key}' must be {rng}{extra}, got {v}.")
        return v

    if t == "number":
        # A finite number, whole or not (a size with size_decimals on).
        try:
            v = float(raw_value)
        except ValueError:
            raise VTTError(f"Setting '{key}' expects a number.")
        if not math.isfinite(v):
            raise VTTError(f"Setting '{key}' expects a finite number.")
        if "min" in spec and v < spec["min"]:
            raise VTTError(f"Setting '{key}' must be at least {spec['min']}.")
        if "max" in spec and v > spec["max"]:
            raise VTTError(f"Setting '{key}' must be at most {spec['max']}.")
        return int(v) if v.is_integer() else v

    if t == "enum":
        choices = spec["choices"]
        v = raw_value.strip().lower()
        if v in choices:
            return v
        allowed = ", ".join(sorted(choices))
        raise VTTError(f"Setting '{key}' must be one of: {allowed}")

    if t == "str":
        # keep raw as-is; CLI passes a single token
        # (you can extend later to join the rest of args for multi-word strings)
        if key in VAR_NAME_RULES:
            return check_var_name_rule(key, raw_value)
        if key in MAP_VAR_NAME_RULES:
            return check_map_var_name_rule(key, raw_value)
        if spec.get("var_roots"):
            # Comma-separated var roots (`equipped,worn`): a root read as a
            # var path, so a typo is said now rather than walking nothing.
            got = [w.strip() for w in raw_value.split(",")]
            if raw_value.strip() and any(
                    not w or w.startswith("__") or any(c.isspace() for c in w)
                    or "" in w.split(".") for w in got):
                raise VTTError(f"Setting '{key}' takes a comma list of var "
                               f"roots (`equipped,worn`): no empty word, "
                               f"spaces, empty path segment or `__` name.")
            return ",".join(got) if raw_value.strip() else ""
        if spec.get("color"):
            v = raw_value.strip()
            if v.lower() not in TEXT_COLORS and not re.fullmatch(
                    r"#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})", v):
                raise VTTError(f"Setting '{key}' takes a colour name ("
                               f"{', '.join(sorted(TEXT_COLORS))}) or "
                               f"#rrggbb, got `{raw_value}`.")
            return v
        if key in _FORMAT_RULE_CHECKS:
            # Rules holding a small format: a typo used to be stored and
            # then read as nothing (`hp::l5` dropped the cap, L25).
            return _FORMAT_RULE_CHECKS[key](key, raw_value)
        words = spec.get("word_list")
        if words is not None:
            # A comma list of known words; a typo'd one used to be ignored.
            got = [w.strip() for w in raw_value.split(",") if w.strip()]
            bad = [w for w in got if w not in words]
            if bad:
                raise VTTError(f"Setting '{key}' takes a comma list of: "
                               f"{', '.join(words)} (not "
                               f"{', '.join(bad)}).")
            return ",".join(got)
        choices = spec.get("choices")
        if choices and raw_value not in choices and not (
                key == "part_to_main_cap_default"
                and re.fullmatch(r"absolute:\d+", raw_value)):
            # A typo'd mode used to be stored and then read as the default.
            extra = (", or absolute:<n>" if key == "part_to_main_cap_default"
                     else "")
            raise VTTError(f"Setting '{key}' must be one of: "
                           f"{', '.join(choices)}{extra}")
        return raw_value

    if t == "list":
        # Structured list-valued rules (currently: default_clamps) aren't
        # editable via the flat key=value !system set command. Route the GM
        # to the dedicated commands instead.
        raise VTTError(
            f"Setting '{key}' is a structured list and can't be edited via "
            f"!system set. Use the dedicated commands for this rule "
            f"(e.g. !gclamp add/remove/list for default_clamps)."
        )

    if t == "dict":
        # Structured dict-valued rules (currently: event_log_format) aren't
        # editable via the flat key=value !system set command either.
        raise VTTError(
            f"Setting '{key}' is a structured dict and can't be edited via "
            f"!system set. Use the dedicated command for this rule "
            f"(e.g. !log format <type> <template> for event_log_format)."
        )

    raise VTTError(f"Invalid schema for setting '{key}'.")


def _dominant_axis_dir(dx: int, dy: int, *, eight_way: bool = False) -> Direction:
    """Pick a facing direction from a (dx, dy) vector pointing where the
    entity should look. Ties prefer vertical for the cardinal case
    (preserves the historical behavior of the 4-way version).

    In 8-way mode, when both components are non-zero we return a diagonal;
    a pure-axis vector still resolves to the matching cardinal.
    """
    if eight_way and dx != 0 and dy != 0:
        v = "up" if dy < 0 else "down"
        h = "left" if dx < 0 else "right"
        return f"{v}_{h}"
    if abs(dy) >= abs(dx):
        return "down" if dy > 0 else "up"
    return "right" if dx > 0 else "left"


def _default_facing_for(
    x: int, y: int, width: int, height: int, *, eight_way: bool = False,
) -> Direction:
    cx = (width + 1) / 2
    cy = (height + 1) / 2
    dx = cx - x
    dy = cy - y
    return _dominant_axis_dir(int(round(dx)), int(round(dy)), eight_way=eight_way)


# ---------- Special/reserved id registry (like how "this" or "current" is the entity whose turn it is right now, "self" is usually the entity directly affected ay a command regardless of turn order") ----------


RESERVED_IDS: Set[str] = {"current", "this", "self", "parent"}

_UNREACHABLE_IDS: Optional[frozenset] = None


def check_status_name(name: Any) -> None:
    """Raise unless `name` can name a status: one word that a status token
    can address (`removes`, `blocked_by`, immunity, dispel read `tag:<x>`
    as a tag and a comma as a list)."""
    if not isinstance(name, str) or not name or any(c.isspace() for c in name):
        raise VTTError(f"`{name}` can't be a status name: one word, no "
                       f"spaces.")
    if name.startswith("tag:") or "," in name:
        raise VTTError(f"`{name}` can't be a status name: a status token "
                       f"reads `tag:...` as a tag and a comma as a list.")


def unreachable_id(eid: Any) -> bool:
    """Whether `entity[<eid>]` would read something else than the unit with
    that id: a hook / action binding (`target`, `actor`, `slot`, ...), a
    Python keyword or `True` / `None`. Such ids are refused when a unit is
    created, like the RESERVED_IDS tokens."""
    global _UNREACHABLE_IDS
    if _UNREACHABLE_IDS is None:
        from formula import HOOK_CONTEXT_NAMES, _ACTION_BINDING_NAMES
        _UNREACHABLE_IDS = frozenset(
            set(HOOK_CONTEXT_NAMES) | set(_ACTION_BINDING_NAMES)
            | set(keyword.kwlist) | {"entity", "true", "false", "none"})
    return str(eid) in _UNREACHABLE_IDS

# Reserved var PATHS: entity FIELDS that formulas read as if they were vars
# (`entity[x].name`, `entity[x].x`), resolved from the Entity itself. Their
# names are reserved: no entity var may be created under them (write_var
# refuses), so a read can never be ambiguous. Formula writes are refused too;
# `name` changes via `!ent rename`, x/y via `!ent tp`.
RESERVED_VAR_PATHS: Tuple[str, ...] = ("x", "y", "name", "map")


# Words a map can't be named: `view` and `all` are map VALUES (the channel's
# viewed map, every map), and the rest are `!map` subcommands or words, so
# `!map <name>` (render that map) never shadows one. vtt_commands checks at
# import that every `!map` subcommand is listed here.
MAP_RESERVED_NAMES = frozenset({
    "view", "all", "clear", "full", "none",
    "colors", "cell", "preview", "ent_sight", "background", "border", "mode",
    "scene", "image", "color", "teamcolor", "resize", "layer", "autoupdate",
    "legend", "coords", "pan", "center", "new", "list", "delete", "rename",
    "copy", "use", "var", "fog", "unseen", "attach", "detach", "void",
    "shape"})


def check_map_name(name: Any) -> None:
    """Raise unless `name` can name a map: id characters, not reserved."""
    if not isinstance(name, str) or not ID_RE.fullmatch(name):
        raise VTTError(
            f"A map name can use letters, digits, `_` and `-` only (1-40 "
            f"characters); `{name}` can't be one.")
    if name.lower() in MAP_RESERVED_NAMES:
        raise VTTError(f"`{name}` is a reserved word, so it can't name a map.")


def check_zone_name(name: Any) -> None:
    """Raise unless `name` can name a zone: id characters, as a map name
    (a backtick or a space broke every reply quoting it)."""
    if not isinstance(name, str) or not ID_RE.fullmatch(name):
        raise VTTError(
            f"A zone name can use letters, digits, `_` and `-` only (1-40 "
            f"characters); `{name}` can't be one.")


def check_grid_dimensions(width: Any, height: Any, rules: Dict[str, Any],
                          where: str) -> None:
    """Refuse a grid side over the max_grid_dimension rule (-1 = no cap)."""
    try:
        cap = int(rules.get("max_grid_dimension", 500))
    except (TypeError, ValueError):
        cap = 500
    if cap < 0:
        return
    for label, v in (("width", width), ("height", height)):
        if isinstance(v, int) and not isinstance(v, bool) and v > cap:
            raise VTTError(
                f"{where}: {label} {v} is over the max_grid_dimension of {cap} "
                f"(the max_grid_dimension rule; -1 = unlimited).")


def check_store_path(path: Any, what: str = "path") -> None:
    """Refuse a dotted path with an empty segment before anything is stored
    under it. `.lead`, `trail.` and `inventory..sword` used to create keys
    named "" (inventory[""]["sword"]) instead of reporting the typo."""
    p = str(path)
    if not p:
        raise VTTError(f"{what} cannot be empty.")
    if "" in p.split("."):
        raise VTTError(f"{what} '{p}' has an empty segment (a doubled, "
                       f"leading or trailing dot).")


def check_no_value_ancestor(root: Any, path: str, where: str) -> None:
    """Refuse writing at `path` under `root` when a key on the way holds a
    value (a number, a string, a list): `k.x` while k = 5. Unit vars, team
    data and match vars used to replace the 5 with {x: ...} without a word,
    while tiles, zones and statuses refused; every store now refuses."""
    keys = str(path).split(".")
    cur = root
    for i, k in enumerate(keys[:-1]):
        if not isinstance(cur, dict) or k not in cur:
            return
        cur = cur[k]
        if not isinstance(cur, dict):
            at = ".".join(keys[:i + 1])
            raise VTTError(
                f"{where} value at '{at}' is {type(cur).__name__}, not a dict "
                f"— cannot set a nested key under it without clobbering.")


# Bounds on one stored value (_own_value): deeper nesting can't be copied or
# written to JSON (Python's recursion limit, ~500 levels), and a value
# holding the same big list many times, small in memory, is written out in
# full: past either, every save of the server would fail from then on.
STORE_DEPTH_LIMIT = 100
STORE_SIZE_LIMIT = 1_000_000
# Python's int-to-text limit: a longer integer can't be shown or saved.
STORE_INT_DIGITS = 4300


def _own_value(value: Any, _budget: Optional[List[int]] = None,
               _depth: int = 0) -> Any:
    """`value` ready to store: a dict or list is deep-copied so the store owns
    it (no object shared with another var, team, tile, zone or status),
    scalars pass through unchanged. Dict keys become strings, as a save/load
    makes them: `{1: 5}` stored by a formula couldn't be reached by the path
    `d.1` until a reload turned the key into '1'. Tuples become lists for the
    same reason (a stored coordinate stops equalling (3, 3) after a reload
    otherwise). A value that couldn't be saved is refused: nested deeper than
    STORE_DEPTH_LIMIT, more than STORE_SIZE_LIMIT values in all, or an
    integer over STORE_INT_DIGITS digits."""
    if _budget is None:
        _budget = [STORE_SIZE_LIMIT]
    _budget[0] -= 1
    if _budget[0] < 0:
        raise VTTError(f"Can't store a value holding more than "
                       f"{STORE_SIZE_LIMIT} values in all.")
    if isinstance(value, (dict, list, tuple)) and _depth >= STORE_DEPTH_LIMIT:
        raise VTTError(f"Can't store a value nested more than "
                       f"{STORE_DEPTH_LIMIT} levels deep.")
    if isinstance(value, dict):
        return {str(k): _own_value(v, _budget, _depth + 1)
                for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        # Coordinates are lists (a save/load turns tuples into lists).
        return [_own_value(v, _budget, _depth + 1) for v in value]
    store = getattr(type(value), "store_value", None)
    if store is not None:
        # An action's `location` target (action.Coord) stores as [x, y].
        return _own_value(store(value), _budget, _depth)
    if (isinstance(value, int) and not isinstance(value, bool)
            and value.bit_length() > 3.3 * STORE_INT_DIGITS
            and (value >= 10 ** STORE_INT_DIGITS
                 or value <= -10 ** STORE_INT_DIGITS)):
        raise VTTError(f"Can't store an integer of more than "
                       f"{STORE_INT_DIGITS} digits.")
    if isinstance(value, float) and not math.isfinite(value):
        # JSON has no inf / nan: a stored one was written as `Infinity`,
        # which other JSON readers refuse.
        raise VTTError(f"Can't store {value}: only finite numbers can be "
                       f"stored.")
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    # Anything else (a function named as a value — `entity[a].f = min` —
    # a set, an object) can't be saved: it used to be stored as-is, after
    # which `!store save` failed and `!ent dump` crashed on that match.
    what = ("a function" if callable(value)
            else f"a {type(value).__name__}")
    raise VTTError(f"Can't store {what}: only numbers, text, true/false, "
                   f"None, lists and dicts can be stored.")


def _window_bounds(viewport: Any, gw: int, gh: int
                   ) -> Tuple[int, int, int, int]:
    """(x0, y0, x1, y1): the grid cells a render window (vx, vy, vw, vh)
    shows, clamped to the grid; the whole grid without one."""
    if viewport is None:
        return 1, 1, gw, gh
    vx, vy, vw, vh = viewport
    return max(1, vx), max(1, vy), min(gw, vx + vw - 1), min(gh, vy + vh - 1)


def same_value(a: Any, b: Any) -> bool:
    """Whether two stored values are the same, types included: Python's ==
    takes 1, 1.0 and True (0, 0.0, False) for one value, and the engine
    reads them differently (vitals refuse a bool, a layer reads True as
    junk), so every "did it change" decision on stored data uses this
    (J17). A walk at C-like speed for the shapes the engine stores."""
    if a is b:
        return True
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        if len(a) != len(b):
            return False
        for k, v in a.items():
            if k not in b or not same_value(v, b[k]):
                return False
        return True
    if isinstance(a, (list, tuple)):
        return len(a) == len(b) and all(
            same_value(x, y) for x, y in zip(a, b))
    return a == b


def _first_difference(a: Any, b: Any, path: str = "") -> str:
    """Where two stored values first differ (same_value), as a dotted path
    with both sides (FCS_SPATIAL_CHECK reports)."""
    if type(a) is dict and type(b) is dict:
        for k in list(a) + [k for k in b if k not in a]:
            if k not in a or k not in b or not same_value(a[k], b[k]):
                if k in a and k in b:
                    return _first_difference(a[k], b[k], f"{path}.{k}")
                return (f"{path}.{k}: "
                        f"{repr(a.get(k, '<none>'))[:60]} -> "
                        f"{repr(b.get(k, '<none>'))[:60]}")
    return f"{path}: {repr(a)[:60]} -> {repr(b)[:60]}"


_JSON_ATOMS = frozenset({str, int, float, bool, type(None)})

# The two JSON forms of a match state: the files' (compact, keys in memory
# order, storage._dump) and the journal hash's (sorted keys, journal.
# state_hash). One encoder each, shared (json.dumps builds one per call).
_JSON_FILE = json.JSONEncoder(separators=(",", ":"))
_JSON_HASH = json.JSONEncoder(sort_keys=True, default=str)


def state_text(state: Dict[str, Any], match: Optional["Match"] = None,
               sort: bool = False) -> str:
    """json.dumps of a match state (Match.to_dict), the same text, built
    from the cached text of each unit, tile and zone of `match` whose
    serialized form the state holds (Entity.ser_dict, Map.ser_tiles /
    ser_zones): a command that changed one unit encodes that unit. `sort`
    = the journal hash's form (sorted keys, default separators), else the
    files' (compact). A state of another time (a snapshot read back)
    encodes its pieces anew."""
    enc = _JSON_HASH if sort else _JSON_FILE
    isep, ksep = (", ", ": ") if sort else (",", ":")
    mode = 1 if sort else 0
    ekey = enc.encode

    def obj(d: Dict[str, Any], value) -> str:
        keys = sorted(d) if sort else d
        return "{" + isep.join(ekey(k) + ksep + value(k, d[k])
                               for k in keys) + "}"

    def plain(_k: Any, v: Any) -> str:
        return ekey(v)

    ents = match.entities if match is not None else {}
    maps = match.maps if match is not None else {}

    def unit(eid: str, piece: Any) -> str:
        e = ents.get(eid)
        if e is None:
            return ekey(piece)
        dd = e.__dict__
        txt = dd.get("_txt")
        if txt is not None and txt[mode] is not None \
                and txt[mode][0] is piece:
            return txt[mode][1]
        text = ekey(piece)
        if dd.get("_ser") is piece:
            if txt is None:
                txt = dd["_txt"] = [None, None]
            txt[mode] = (piece, text)
        return text

    def pieces(mp: Optional["Map"], kind: str, d: Any) -> str:
        if mp is None or type(d) is not dict:
            return ekey(d)
        whole = mp._ptxt.get((kind, mode))
        if whole is not None and whole[0] is d:
            return whole[1]
        cache = mp._ptxt.get((kind, mode, "items")) or {}
        fresh: Dict[str, Any] = {}

        def one(k: str, v: Any) -> str:
            hit = cache.get(k)
            if hit is not None and hit[0] is v:
                fresh[k] = hit
                return hit[1]
            t = ekey(v)
            fresh[k] = (v, t)
            return t
        text = obj(d, one)
        mp._ptxt[(kind, mode, "items")] = fresh
        mp._ptxt[(kind, mode)] = (d, text)
        return text

    def one_map(name: str, md: Any) -> str:
        mp = maps.get(name)
        if mp is None or type(md) is not dict:
            return ekey(md)
        return obj(md, lambda k, v: pieces(mp, k, v)
                   if k in ("tiles", "zones") else ekey(v))

    def top(k: str, v: Any) -> str:
        if k == "entities" and type(v) is dict:
            return obj(v, unit)
        if k == "maps" and type(v) is dict:
            return obj(v, one_map)
        return ekey(v)

    text = obj(state, top)
    if SPATIAL_CHECK:
        want = (json.dumps(state, sort_keys=True, default=str) if sort
                else json.dumps(state, separators=(",", ":")))
        if text != want:
            raise SpatialCheckError("state_text differs from json.dumps")
    return text


def jcopy(v: Any) -> Any:
    """A deep copy of a stored value, ~4x faster than copy.deepcopy for
    the JSON shapes the engine stores (dicts, lists, text, numbers, bools,
    None); anything else (a set, a tuple) goes to copy.deepcopy."""
    t = type(v)
    if t is dict:
        return {k: (x if type(x) in _JSON_ATOMS else jcopy(x))
                for k, x in v.items()}
    if t is list:
        return [x if type(x) in _JSON_ATOMS else jcopy(x) for x in v]
    if t in _JSON_ATOMS:
        return v
    return copy.deepcopy(v)


def json_text(data: Any) -> str:
    """The JSON text a save file holds (raises VTTError on a value JSON
    can't hold)."""
    try:
        return json.dumps(data, indent=2)
    except (TypeError, ValueError) as e:
        raise VTTError(f"the data holds a value that can't be saved ({e}).")


def write_json_file(path: str, data: Any) -> None:
    """Write `data` as JSON to `path` all-or-nothing (see write_text_file)."""
    write_text_file(path, json_text(data))


def write_text_file(path: str, text: str) -> None:
    """Write `text` to `path` all-or-nothing: it goes to a temp file beside
    the target, then is moved over it. json.dump straight into the target
    truncated an existing good save when serialization failed partway.
    Raises VTTError (no host path in the message: callers name the file the
    way they show it)."""
    folder = os.path.dirname(os.path.abspath(path))
    tmp = os.path.join(folder, f".{os.path.basename(path)}.{uuid.uuid4().hex}.tmp")
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(text)
        os.replace(tmp, path)
    except OSError as e:
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise VTTError(f"the file couldn't be written ({e.strerror or e}).")


def reserved_var_path_error(path: str, where: str) -> Optional[str]:
    """The refusal message for a write at `path` whose first segment is a
    reserved var path, or None when the path is an ordinary var."""
    seg0 = path.split(".", 1)[0]
    if seg0 not in RESERVED_VAR_PATHS:
        return None
    fix = {"name": "`!ent rename <id> <name>`",
           "map": "`!ent tp <id> <x> <y> <map>`"}.get(
               seg0, "`!ent tp <id> <x> <y>`")
    return (f"{where}: `{seg0}` is a reserved var path (the entity's own "
            f"{reserved_path_meaning(seg0)}); it can't be written or nested "
            f"under. Use {fix}.")


def reserved_path_meaning(seg0: str) -> str:
    """What reserved var path `seg0` reads on a unit, for messages."""
    return {"name": "display name", "map": "map"}.get(seg0, "position")

def checked_unit_vars(vars_: Any, vitals: Iterable[str], where: str,
                      team_var: Optional[str] = None,
                      tags_var: Optional[str] = None) -> Dict[str, Any]:
    """`vars_` ready to become a whole unit's vars, held to the rules
    write_var applies one write at a time: each vital var present (hp /
    max_hp / initiative) is a whole number (a numeric string or float is
    coerced; text, a bool, a dict or a non-finite number is refused), no
    top-level key is a reserved var path (x / y / name) or empty, and the
    dict is the unit's own copy with string keys. Spawn (summon templates,
    part / segment templates) and transform set a unit's vars wholesale;
    they used to store `hp: 'abc'` as given, and the unit then broke
    `!list` and every hp read."""
    if not isinstance(vars_, dict):
        raise VTTError(f"{where}: vars must be a dict, got "
                       f"{type(vars_).__name__}.")
    out = _own_value(vars_)
    for k in list(out):
        if k == "":
            raise VTTError(f"{where}: a var has an empty name.")
        if k in RESERVED_VAR_PATHS:
            raise VTTError(
                f"{where}: `{k}` is a reserved var path (the unit's own "
                f"{reserved_path_meaning(k)}), so a "
                f"template or statblock can't carry a var by that name.")
    for k in vitals:
        if k not in out:
            continue
        coerced = _coerce_vital_value(out[k])
        if coerced is None:
            raise VTTError(f"{where}: vital var '{k}' must be a finite "
                           f"whole number, got {out[k]!r}.")
        out[k] = coerced
    if team_var and team_var in out:
        t = team_text(out[team_var])
        if t is None:
            raise VTTError(f"{where}: team var '{team_var}' must be text or "
                           f"a number, got {out[team_var]!r}.")
        out[team_var] = t
    if tags_var:
        out = checked_tag_vars("", out, tags_var, where)
    return out


# Status instance fields the engine does arithmetic on (stacking, extend,
# counters, the `name(level)` display).
STATUS_NUMBER_FIELDS: Tuple[str, ...] = ("level", "duration")


def _coerce_number(v: Any) -> Optional[Any]:
    """`v` as a finite int or float (a numeric string is parsed), or None.
    bool is refused (True is not level 1)."""
    if isinstance(v, bool):
        return None
    if isinstance(v, int):
        return v
    if isinstance(v, str):
        t = v.strip()
        try:
            return int(t)
        except ValueError:
            try:
                v = float(t)
            except ValueError:
                return None
    if isinstance(v, float):
        return v if math.isfinite(v) else None
    return None


def checked_status_value(path: str, value: Any, where: str) -> Any:
    """`value` ready to store at `path` in a status instance (or a status
    definition's seed data): `level` and `duration` must be finite numbers
    with nothing nested under them. `!ent status a set burn level abc` used
    to be stored, and the next `!status apply` crashed on it."""
    seg0 = str(path).split(".", 1)[0]
    if seg0 not in STATUS_NUMBER_FIELDS:
        return value
    if "." in str(path):
        raise VTTError(f"{where}: `{seg0}` is a number field of a status; "
                       f"nothing can be nested under it.")
    n = _coerce_number(value)
    if n is None:
        raise VTTError(f"{where}: `{seg0}` must be a finite number, "
                       f"got {value!r}.")
    return n


# `entity[self].<var path> <op> <number>`, the shape of the default death
# condition: read without building a formula namespace (~2 ms each), since
# the death check runs after every var write and status change (X15).
# No leading whitespace and no leading zeros (`007`): the formula engine
# refuses both, so they go to it and read as it reads them (L42).
_SIMPLE_VAR_TEST_RE = re.compile(
    r"^entity\[self\]\.([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*)\s*"
    r"(<=|>=|==|!=|<|>)\s*(-?(?:0|[1-9]\d*)(?:\.\d+)?)\s*$")


def _simple_var_test(cond: str, e: Any) -> Optional[bool]:
    """The value of condition `cond` on unit `e` when it is a plain
    `entity[self].<path> <op> <number>` over a stored number, the way the
    formula reads it; None when it isn't (the caller runs the formula)."""
    mo = _SIMPLE_VAR_TEST_RE.match(cond or "")
    if mo is None:
        return None
    path, op, num = mo.group(1), mo.group(2), mo.group(3)
    if path.split(".")[0] in RESERVED_VAR_PATHS or "__" in path:
        return None
    cur: Any = e.vars
    for seg in path.split("."):
        if not isinstance(cur, dict) or seg not in cur:
            return None
        cur = cur[seg]
    if isinstance(cur, bool) or not isinstance(cur, (int, float)):
        return None
    n = float(num) if "." in num else int(num)
    return {"<=": cur <= n, ">=": cur >= n, "==": cur == n, "!=": cur != n,
            "<": cur < n, ">": cur > n}[op]


# The largest total a status resistance fold may reach (E6): a level or a
# duration past it means a record overflowed, so the record is skipped.
RESIST_TOTAL_MAX = 1e15


# Recognized modifier fold ops (see Match._apply_modifier_op). An op outside
# this set still folds as a lenient add, but `!mod show` flags it as a likely
# typo via Match.unknown_modifier_ops.
MODIFIER_OPS: Tuple[str, ...] = ("add", "inc%", "more%", "set", "min", "max")


# -------------------------
# Passive hooks & Passive dataclass
# -------------------------

# Valid `when` values for passives. Entity passives fire on the owning
# entity's own turn/round; global passives fire once per entity in turn order
# on each hook (per-entity iteration).
# ----------------------------------------------------------------------------
# HOOK_NAMES: every valid value for Passive.when.
#
# Hooks split into two families:
#
# 1. Turn/lifecycle hooks (no var-event payload):
#    - on_turn_start       fired before each entity's turn
#    - on_turn_end         fired after each entity's turn
#    - on_round_start      fired before each round (once per entity in turn_order)
#    - on_round_end        fired after each round (once per entity in turn_order)
#    - on_entity_spawned   fired once when an entity is spawned via Entity.spawn
#
#    For these, formula context exposes: this, self. Var-event bindings
#    (changed_key, old_value, new_value, hook_name) are bound to None.
#
# 2. Var hooks (carry a payload describing a single var-event):
#    - on_var_created      a previously-nonexistent path was just created.
#                          Fired at EVERY level along a path that's newly
#                          created. Example: writing inventory.gold.coins=50
#                          when inventory didn't exist fires three events:
#                          'inventory', then 'inventory.gold', then
#                          'inventory.gold.coins' (top-down ordering).
#                          old_value is None; new_value is the value at that
#                          path (which may itself be a dict for non-leaf
#                          levels).
#
#    - on_var_changed      an existing path was overwritten with a different
#                          value. Fired only on the leaves whose values
#                          actually differ — overwriting a parent dict does
#                          NOT fire a change event on the parent unless the
#                          parent itself genuinely differs after the diff.
#                          old_value and new_value are both populated.
#
#    - on_var_removed      a previously-existing path no longer exists.
#                          Fired at every level that ceased to exist,
#                          bottom-up (leaves first, then their containers).
#                          old_value carries the full previous subtree (so
#                          'log what got destroyed' passives can inspect it);
#                          new_value is None.
#
#    - on_var_written      catch-all. Fires alongside every created/changed/
#                          removed event. Use the `hook_name` context binding
#                          to discriminate (it'll be one of the three above,
#                          NOT 'on_var_written' itself).
#                          NOTE: on_var_written does NOT include attempt
#                          events. on_var_write_attempt is a separate channel
#                          for "an attempt happened" vs "data changed." A
#                          passive that wants to audit literally every write
#                          activity should subscribe to BOTH on_var_written
#                          AND on_var_write_attempt.
#
#    - on_var_write_attempt
#                          Fires for every write call BEFORE the mutation,
#                          regardless of whether the resulting diff is empty.
#                          This closes the "no-event" gap: a heal at full HP
#                          produces no on_var_changed event (since old==new
#                          after clamping), but on_var_write_attempt still
#                          fires — so passives that need to count attempted
#                          actions (overheal magnitude tracking, "every heal
#                          ever logged") can observe them.
#
#                          The hook fires AFTER clamp computation but BEFORE
#                          the actual mutation. Context bindings:
#                            old_value      current state at the path
#                            new_value      what will be stored (post-clamp)
#                            intended_value what the caller requested (pre-clamp)
#                            was_clamped    True iff clamping changed new_value
#                                           (False on bypassed writes — bypass
#                                           skips clamping, so nothing was
#                                           clamped)
#                            hook_name      "on_var_write_attempt"
#
#                          Fires on bypassed writes (bypass affects clamping,
#                          not observability). Does NOT fire on remove_var or
#                          remove_var_silent — those have no "no-op" gap that
#                          needs filling (remove raises if the path is absent).
#
# Passives subscribing to var hooks use the `target` + `scope` fields on
# Passive to filter which events they care about. See the Passive class
# docstring for details.
# ----------------------------------------------------------------------------
HOOK_NAMES: Set[str] = {
    "on_turn_start",
    "on_turn_end",
    "on_round_start",
    "on_round_end",
    "on_entity_spawned",
    # Despawn event: the unit is leaving the match WITHOUT dying — `!ent
    # remove`, `!part remove`, remove_entity(), the body parts and snake
    # segments removed along with it, `!ent transfer` out of the match, and
    # the old parts a transform drops. Fires on the unit BEFORE it goes, so
    # `self` and its vars/position still resolve. A death fires on_death
    # instead (as do the parts that go into the dying body's corpse).
    "on_entity_despawned",
    # A unit lost its turn to a `skips_turn` status. Fires on that unit
    # (`self`), with `skip_status` = the status name(s) responsible, right
    # after the "turn skipped" line and before the turn moves on (so before
    # any round wrap that skip causes).
    "on_turn_skipped",
    # Death event. Fires on the entity once the death-condition formula
    # evaluates truthy, BEFORE the entity is removed from the match (so
    # `self` is still bound and entity[self].x/.y still resolve). The
    # corpse-vs-delete result also runs after this fires. No special
    # extras — passives observe via the normal `self`/`this` bindings.
    "on_death",
    # Revive event. Fires on the freshly-restored entity AFTER revive()
    # has spawned it back from a corpse (so on_entity_spawned has
    # already fired). Useful for "remove the doomed status when I come
    # back" or "regen kicks in only after the first revive". `self` =
    # the revived entity; `this` = current-turn entity as usual.
    "on_revive",
    # Movement event (any position change — tp / step / clone-spawn-
    # via-move; NOT the initial spawn placement, which has its own
    # on_entity_spawned hook). Context bindings during fire:
    #   from_x, from_y, to_x, to_y  — the move's endpoints
    # Tile on_enter / on_exit fire alongside this for tile-attached
    # logic; on_entity_moved is the entity-side complement so a
    # passive can react regardless of which tile is involved.
    "on_entity_moved",
    # Map change: a unit moved to another map (`!ent tp <id> <x> <y>
    # <map>`, move_entity(..., map)). Fires on the unit after its
    # on_entity_moved, with from_map / to_map bound (on_entity_moved has
    # them too; they are equal for an ordinary move), so a GM who only
    # cares about map changes needs no test.
    "on_entity_changed_map",
    # Nested maps: fired for the units on each map a unit carries (its
    # inner maps, `!map attach`) when that unit completes a move — a
    # step, a teleport, a change of maps — with `map_vehicle` bound.
    "on_map_vehicle_moved",
    # Fired for each occupant of a dying map vehicle's inner maps, after
    # that occupant's death effect (map_vehicle_death_effect), with
    # `map_vehicle` bound.
    "on_map_vehicle_death",
    # Action usage event. Fires AFTER an action body has run to
    # completion (and after its outer snapshot has been committed). A
    # passive watching this hook sees the final state, not an in-flight
    # one. Fires on the ACTOR entity (`self` = the entity that used the
    # action; `this` = current-turn entity, as usual). Context bindings:
    #   action_name   the bare name (e.g. "slice")
    #   action_path   the full vars path the action was loaded from
    #                 (e.g. "inventory.sword.actions.slice"). Useful
    #                 for category filtering (`if action_path.startswith
    #                 ("inventory.")`).
    #   target        the resolved target — an entity id (target=entity),
    #                 a (x, y) tuple (target=location), a list of either,
    #                 or None (target=none).
    #   args          the args dict the GM passed (key=value tokens).
    # Failed actions (fail() / rollback) do NOT fire this hook — only
    # successful completions do; the on_action_failed hook below
    # covers the rollback path.
    "on_action_used",
    # Target-side companion to on_action_used. Fires on EACH ENTITY
    # the action targeted, AFTER the actor-side on_action_used has
    # run. For target=entity, fires once on that target. For
    # target=entity_list, fires once per eid (insertion order).
    # For location / location_list / none, does NOT fire — there's
    # no entity-side target. Inside the hook, `self` binds to the
    # target (the entity being acted on); `actor` binds to the
    # entity that USED the action. Other bindings (action_name,
    # action_path, args) match on_action_used. This is where
    # reactive defender logic lives — "shield reflects melee",
    # "trap counters attacker", "this entity has resistance to
    # actions whose action_path starts with `inventory.poison.`".
    "on_action_used_on_target",
    # Failure event. Fires on the ACTOR after a clean fail() abort —
    # AFTER the runner has rolled back to pre-state, so passives see
    # the unchanged world (matching on_action_used's "see settled
    # state" contract). Bindings:
    #   action_name, action_path, target, args  — same as
    #   on_action_used
    #   fail_reason   the GM-supplied tag from fail(reason, msg),
    #                 or "" for the single-arg fail(msg) form
    #   fail_message  the human-readable failure message
    # Engine faults (recursion limit, internal invariants) DON'T
    # fire this hook — they're bugs, not GM-controlled outcomes,
    # and observing them with a passive would mask the diagnostic.
    "on_action_failed",
    # Per-step movement event. Fires ONCE PER CELL traversed during a
    # stepwise move (Entity.move_dirs), AFTER the position changes for
    # that step — so `entity[self].x/.y` refer to the just-entered
    # cell when the passive runs. Context bindings:
    #   from_x, from_y  — the cell just left (the previous step's
    #                     position; equals the entity's pre-move origin
    #                     for the first step)
    #   to_x, to_y      — the cell just entered (== entity[self].x/.y)
    # Single-tp moves (Entity.tp, including formula `move_entity`) fire
    # `on_entity_moved` only, not `on_entity_step` — there are no
    # intermediate cells to "step into". So on_entity_step is the right
    # hook for "thorns trigger per cell of traversal", "attacks of
    # opportunity fire per step adjacent to me", and "distance-cost
    # accumulators". For "did this entity move at all this command",
    # use on_entity_moved (fires once, after all steps).
    "on_entity_step",
    # Status lifecycle. Fire on the entity whose status changed.
    # Context bindings:
    #   status_name  — the affected status
    #   old_value    — for changed/removed: the prior data dict (the
    #                  whole subtree under status[name]); None for
    #                  added (the status didn't exist before).
    #   new_value    — for added/changed: the resulting data dict;
    #                  None for removed (the status no longer exists).
    # `on_status_changed` fires on data-field writes within an
    # already-present status (status_set on a path; the field-level
    # equivalent of on_var_changed). For applied/removed lifecycle,
    # use on_status_added / on_status_removed — they cover the
    # whole-status appear/disappear distinction.
    "on_status_added",
    "on_status_removed",
    "on_status_changed",
    "on_var_created",
    "on_var_changed",
    "on_var_removed",
    "on_var_written",
    "on_var_write_attempt",
    # Mount lifecycle (mounts/vehicles). Fire on the RIDER entity (`self`
    # = the rider; `this` = current-turn entity). Context bindings:
    #   vehicle   — the vehicle's id (new HOOK_CONTEXT name)
    #   slot      — the slot name the rider entered / left
    # on_mounted fires after a rider boards (or switches slots — the
    # switch fires on_dismounted from the old slot then on_mounted in the
    # new); on_dismounted fires after a rider leaves (also on vehicle-death
    # eject). Lets the GM grant a "buckled in" status, deduct fuel, etc.
    "on_mounted",
    "on_dismounted",
    # Fired for each rider of a dying vehicle, after its death effect
    # (mount_death_effect) and before mount_on_vehicle_death settles its
    # fate, with `vehicle` and `slot` bound.
    "on_mount_vehicle_death",
    # A unit took another form: fired on it once the swap settled (its
    # statuses arrived and left), with `transform_kind` bound: transform
    # (`!ent transform`, transform()), replace (`!ent replace`,
    # replace_form()) or revert.
    "on_transformed",
}

# Custom event-bus subscription. A passive whose `when` is "event:<name>"
# (any non-empty name) fires when the GM emits that named event via the
# emit() formula primitive or the !emit command — a user-extensible hook
# surface decoupling cause from effect, on top of the fixed HOOK_NAMES.
_EVENT_WHEN_PREFIX = "event:"


def is_event_hook(when: Any) -> bool:
    """True iff `when` is a custom event-bus subscription ('event:<name>')."""
    return (isinstance(when, str)
            and when.startswith(_EVENT_WHEN_PREFIX)
            and len(when) > len(_EVENT_WHEN_PREFIX))

# Tile hooks live in tiles[(x, y)]["hooks"][<name>] as formula strings.
# Movement hooks (on_enter / on_exit / on_stop) fire when an entity
# transits a tile via Entity.tp / Entity.move_dirs (and
# Match.move_group_dirs for group-shift moves). Time hooks
# (on_round_*, on_turn_*) fire on the tile itself at the corresponding
# round/turn lifecycle moment — they don't need an entity standing on
# the tile, just the tile existing with the hook registered. These
# names are kept separate from HOOK_NAMES because entity / global
# passives don't subscribe to them (only stored tile-side formulas
# do). See Match.fire_tile_hook / Match.fire_tile_time_hooks.
TILE_HOOK_NAMES: Set[str] = {
    # Movement
    "on_enter",   # entity arrived on this tile (fired post-position-change)
    "on_exit",    # entity is about to leave this tile (fired PRE-position-change
                  # so entity[self].x / .y still refer to the exit tile)
    "on_stop",    # entity stopped here: either a tp landed here, or this
                  # was the last cell of a stepwise move. Fires after on_enter
                  # at the same coord.
    # Time hooks. Fire once per relevant tile (anything in match.tiles
    # carrying that hook) at the round/turn lifecycle moment. The
    # firing entity (for `self`) is whatever entity's turn is current
    # at the time the hook fires — except for round_* hooks where no
    # specific entity is acting; there `self` resolves to the
    # current-turn entity if there is one, else `self` is unbound.
    # Bindings: tile_x, tile_y for both movement and time hooks.
    "on_round_start",
    "on_round_end",
    "on_turn_start",
    "on_turn_end",
}

# Zone hooks live in zones[name]["hooks"][<name>] as formula strings. A
# zone is a NAMED set of cells (Match.zones) — unlike a tile (one cell),
# a zone covers many and can be reshaped/moved. Zones carry TWO movement
# hook families plus the time hooks:
#   Boundary hooks (on_enter/on_exit/on_stop) fire ONCE when an entity
#     CROSSES the zone's edge — entering from outside, leaving to outside,
#     or stopping inside. Moving cell-to-cell WITHIN the zone fires none
#     of these. This is the "you entered the room" semantics.
#   Per-cell hooks (on_cell_enter/on_cell_exit/on_cell_stop) mirror tile
#     movement hooks: they fire for EVERY cell of the zone stepped into /
#     out of / stopped on, even while moving within the zone. This is the
#     "the gas damages you each cell you walk through" semantics.
#   Time hooks (on_round_*, on_turn_*) fire once per zone carrying them
#     at the lifecycle moment, like tile time hooks.
# Bindings: zone_name, plus tile_x/tile_y (the crossed/stepped cell) for
# movement hooks. `self` = the moving/acting entity (or current-turn
# entity for time hooks; unbound if none). Kept separate from HOOK_NAMES
# and TILE_HOOK_NAMES — only zone-stored formulas subscribe. See
# Match.fire_zone_hook / fire_zone_move_hooks / fire_zone_time_hooks.
ZONE_HOOK_NAMES: Set[str] = {
    # Boundary (fire once on a zone-edge crossing)
    "on_enter",
    "on_exit",
    "on_stop",
    # Per-cell (fire per cell of the zone, like tile hooks)
    "on_cell_enter",
    "on_cell_exit",
    "on_cell_stop",
    # Time
    "on_round_start",
    "on_round_end",
    "on_turn_start",
    "on_turn_end",
}
# Reserved top-level keys inside a zone dict (everything else under
# zones[name]["data"] is free-form GM data). `anchor`/`anchor_radius`/
# `anchor_metric` make a zone an entity-anchored AURA: its cells are
# re-stamped (a radius around the anchor entity's footprint) whenever
# the anchor moves. They're reserved so `!zone set` / zone_set can't
# clobber the binding.
ZONE_RESERVED_KEYS = frozenset({
    "cells", "data", "hooks", "glyph",
    "anchor", "anchor_radius", "anchor_metric",
})

# Var hooks distinguished from lifecycle hooks. Useful for code paths that
# need to know whether to expect a var-event payload.
VAR_HOOKS: Set[str] = {
    "on_var_created",
    "on_var_changed",
    "on_var_removed",
    "on_var_written",
    "on_var_write_attempt",
}

# Valid values for Passive.scope (var-hook filtering).
#   exact     — fires only when changed_key == target
#   children  — fires when changed_key is a direct child of target
#               (exactly one path segment deeper)
#   deep      — fires when changed_key is target itself OR any descendant
#               (used with target="" for entity-wide watch)
PASSIVE_SCOPES: Set[str] = {"exact", "children", "deep"}


def checked_priority(v: Any, what: str = "priority") -> Any:
    """A priority: a finite number (an integral float reads as an int),
    text holding one included; higher runs or folds first."""
    if isinstance(v, str):
        try:
            v = float(v.strip())
        except ValueError:
            raise VTTError(f"{what} must be a number, got {v!r}.")
    if isinstance(v, bool) or not isinstance(v, (int, float)) \
            or not math.isfinite(v):
        raise VTTError(f"{what} must be a finite number, got {v!r}.")
    # A huge whole number stays a float, so a listing prints 1e+308, not
    # its 309 digits.
    return int(v) if float(v).is_integer() and abs(v) < 1e15 else v


@dataclass
class Passive:
    """
    A passive ability — either entity-scoped (stored on Entity.passives) or
    global (stored on Match.global_passives). The `formula` is run as a
    program (assignments allowed; trailing expression value is logged) each
    time `when` fires for the appropriate target entity.

    Inside the formula:
      this = entity whose turn it currently is (Match.current_entity_id())
      self = the target entity for this firing
             - for entity passives: always the owning entity
             - for global passives: each entity iterated for the hook

    For var hooks (on_var_created/changed/removed/written), the formula also
    has access to:
      changed_key   the dotted path that fired this event (e.g. "inventory.sword")
      old_value     the value before the event (None for created)
      new_value     the value after the event  (None for removed)
      hook_name     one of "on_var_created", "on_var_changed", "on_var_removed"
                    (NEVER "on_var_written" — that's just the catch-all
                    subscription. Use hook_name to discriminate inside an
                    on_var_written passive.)

    For non-var hooks, all four bindings above are None.

    --- Filtering var hooks: `target` + `scope` ---

    Var hooks fire potentially many events per write. To prevent every var
    passive firing on every write, var-hook passives filter via `target` and
    `scope`:

      target   The dotted path being watched. Empty string ("") = entity root.
               Examples: "hp", "inventory", "inventory.sword.damage", "".

      scope    How the target relates to the event's changed_key:
                 "exact"    — fires only when changed_key == target.
                              Example: target="hp" catches writes to hp itself.
                 "children" — fires when changed_key is a direct child of target
                              (exactly one segment deeper).
                              Example: target="inventory" catches
                              "inventory.sword" but NOT "inventory.sword.damage".
                              With target="" (root), catches every top-level var.
                 "deep"     — fires when changed_key equals target OR is anywhere
                              below it. Example: target="inventory" catches
                              "inventory", "inventory.sword", and
                              "inventory.sword.damage". With target="" (root),
                              catches every var-event on the entity (entity-wide
                              watch).

    For non-var hooks (turn/round/spawn), target and scope are ignored.
    """
    id: str
    when: str
    formula: str
    # Filtering for var hooks. Defaults give "catch everything on this entity"
    # behavior, which is the safest default for non-var hooks too (since they
    # ignore these fields entirely).
    target: str = ""
    scope: str = "deep"
    # Order within one hook firing: highest first, across global, team and
    # own passives (Match._ordered_passives); ties keep that order.
    priority: float = 0
    # Extra turns (#224): whether this passive fires on an extra turn's
    # on_turn_start / on_turn_end. None = the extra_turn_passives rule.
    extra_turns: Optional[bool] = None

    def __post_init__(self):
        if not isinstance(self.id, str) or not self.id.strip():
            raise VTTError("Passive id must be a non-empty string.")
        self.priority = checked_priority(self.priority, "Passive priority")
        if self.extra_turns is not None and \
                not isinstance(self.extra_turns, bool):
            raise VTTError("Passive extra_turns must be true, false or unset.")
        if self.when not in HOOK_NAMES and not is_event_hook(self.when):
            allowed = ", ".join(sorted(HOOK_NAMES))
            raise VTTError(
                f"Unknown passive hook '{self.when}'. Allowed: {allowed}; "
                f"or a custom event subscription 'event:<name>'."
            )
        if not isinstance(self.formula, str):
            raise VTTError("Passive formula must be a string.")
        if not isinstance(self.target, str):
            raise VTTError("Passive target must be a string (use '' for root).")
        if self.scope not in PASSIVE_SCOPES:
            allowed = ", ".join(sorted(PASSIVE_SCOPES))
            raise VTTError(
                f"Unknown passive scope '{self.scope}'. Allowed: {allowed}"
            )

    def matches_event(self, changed_key: str) -> bool:
        """
        Return True if a var-event on `changed_key` should fire this passive.
        Only meaningful for var hooks; non-var hooks ignore target/scope.

        The target is treated as a dotted path. Empty target = root, which
        always matches under "deep" scope (entity-wide watch) and matches
        the immediate top-level keys under "children" scope.
        """
        t = self.target
        if self.scope == "exact":
            return changed_key == t
        if self.scope == "children":
            # Direct children of root (target="") = top-level keys (no dots).
            if t == "":
                return "." not in changed_key
            prefix = t + "."
            if not changed_key.startswith(prefix):
                return False
            return "." not in changed_key[len(prefix):]
        if self.scope == "deep":
            if t == "":
                return True  # entity-wide watch
            if changed_key == t:
                return True
            return changed_key.startswith(t + ".")
        return False  # unreachable given __post_init__ validation

    def to_dict(self) -> Dict[str, Any]:
        d = {
            "id": self.id,
            "when": self.when,
            "formula": self.formula,
            "target": self.target,
            "scope": self.scope,
        }
        if self.priority:
            d["priority"] = self.priority
        if self.extra_turns is not None:
            d["extra_turns"] = self.extra_turns
        return d

    @staticmethod
    def from_dict(d: Dict[str, Any]) -> "Passive":
        # `target=""` is the "no filter" sentinel and `scope="deep"` is the
        # most permissive option — these defaults are the semantic
        # "unspecified" state, not back-compat for missing fields.
        return Passive(
            id=d["id"],
            when=d["when"],
            formula=d["formula"],
            target=d.get("target", ""),
            scope=d.get("scope", "deep"),
            priority=d.get("priority", 0),
            extra_turns=(d.get("extra_turns")
                         if isinstance(d.get("extra_turns"), bool) else None),
        )


# ============================================================================
# Clamp infrastructure
# ============================================================================
# Clamps constrain numeric var writes. A clamp specifies a path being clamped,
# optional max and/or min bounds, and a mode (soft/hard). Clamps live in two
# places:
#   1. The game system's "default_clamps" rule — a list of clamp specs that
#      apply to all entities in matches using that system. Common cases like
#      "hp can't exceed max_hp" belong here.
#   2. Per-entity overrides on Entity.clamps — a dict keyed by path. When an
#      entity defines a clamp on the same path the system does, the entity's
#      clamp wholly replaces the system's for that path (not field-by-field
#      merge — see design discussion in commit notes).
#
# Bounds (max, min) can each be:
#   - a numeric literal (e.g. 100): the absolute bound
#   - a string path (e.g. "max_hp"): resolved against the entity's vars at
#     write time; if the referenced var doesn't exist or isn't numeric, the
#     bound is treated as absent ("no bound") and the clamp doesn't engage
#     in that direction.
#
# Modes:
#   - "hard": every numeric write that would violate the bound is clamped.
#     If hp is 70 (already over max=50), writing 80 still clamps to 50;
#     writing 40 stays at 40 (under bound, fine); writing 60 clamps to 50.
#   - "soft": engages only when a write would push the value across the
#     bound from the LEGAL side. If hp=70/max=50, writing 80 leaves hp at 80
#     (already past — soft is dormant). If hp=30/max=50, writing 80 clamps
#     to 50 (would push from below). Creation is treated as "crossing from
#     below" since there's no prior value — soft engages on initial writes
#     that land out of bounds.
#
# Non-numeric writes (strings, dicts, lists, bools) bypass clamps entirely.
# Booleans are explicitly excluded even though `bool` is a subclass of `int`,
# because semantic equality between True/1 and False/0 would lead to weird
# clamp behavior.
#
# Clamp bypass at command level: !ent set_var ... bypass_clamp=yes (and
# equivalent for other writing commands). When bypassed, the clamp is not
# consulted at all and the raw value is written. The resulting event still
# carries the (un-clamped) intended_value alongside new_value, and
# was_clamped=False since no clamping happened.
# ============================================================================

@dataclass
class ClampSpec:
    """One clamp definition. See module-level docstring for full semantics.

    path        Dotted var path being clamped (e.g. "hp" or "inventory.gold.amount").
    max         Upper bound: numeric literal, dotted path string, or None
                for no upper bound.
    min         Lower bound: same options, None = no lower bound.
    mode        "soft" (engage only when crossing from legal side) or
                "hard" (always enforce).

    At least one of max/min must be set; a clamp with neither is invalid.
    Bounds defined as path strings are resolved against the entity's vars
    at write time, so the bound can dynamically follow another variable
    (e.g. hp clamped by max_hp). If the referenced var is missing or
    non-numeric at write time, the clamp gracefully degrades to "no bound"
    in that direction.
    """
    path: str
    max: Any = None
    min: Any = None
    mode: str = "soft"

    def __post_init__(self):
        if not isinstance(self.path, str) or not self.path.strip():
            raise VTTError("Clamp path must be a non-empty string.")
        if self.mode not in ("soft", "hard"):
            raise VTTError(
                f"Unknown clamp mode '{self.mode}'. Allowed: soft, hard."
            )
        legacy_drop = False
        if LEGACY_IDS_OK.get():
            # Saved data from a build that took any text as a bound (it
            # meant "no bound" there): drop it with a console note, so the
            # file still loads; new input is refused below.
            for label in ("max", "min"):
                b = getattr(self, label)
                if isinstance(b, str) and not re.match(
                        r"[A-Za-z_]\w*(\.\w+)*\Z", b.strip()):
                    print(f"⚠️ Clamp on '{self.path}': dropped the {label} "
                          f"bound {b!r} (a bound is a number or a var path).")
                    setattr(self, label, None)
                    legacy_drop = True
        if self.max is None and self.min is None and not legacy_drop:
            raise VTTError(
                f"Clamp on '{self.path}' must specify at least one of max or min."
            )
        # Validate bound types: numeric literal (int/float, NOT bool) or string path
        for label, b in [("max", self.max), ("min", self.min)]:
            if b is None:
                continue
            if isinstance(b, bool):
                raise VTTError(
                    f"Clamp on '{self.path}' has {label}={b!r}: booleans are not "
                    f"valid bounds. Use a number or var path string."
                )
            if not isinstance(b, (int, float, str)):
                raise VTTError(
                    f"Clamp on '{self.path}' has {label}={b!r}: must be a number "
                    f"or var path string."
                )
            # A string bound names a var (`max_hp`, `stats.cap`); anything
            # else (a formula, spaces) can never name one and meant "no
            # bound" forever, from whichever route it came (a template, a
            # transform form, a summon).
            if isinstance(b, str) and not re.match(
                    r"[A-Za-z_]\w*(\.\w+)*\Z", b.strip()):
                raise VTTError(
                    f"Clamp on '{self.path}' has {label}={b!r}: a bound is a "
                    f"number or a var path (`max_hp`, `stats.cap`).")
        # If both bounds are numeric literals, validate min <= max at config time.
        # We can't validate when either is a path — those resolve at write time.
        if (isinstance(self.max, (int, float)) and not isinstance(self.max, bool)
                and isinstance(self.min, (int, float)) and not isinstance(self.min, bool)
                and self.min > self.max):
            raise VTTError(
                f"Clamp on '{self.path}': min ({self.min}) > max ({self.max})."
            )

    def to_dict(self) -> Dict[str, Any]:
        # Omit None fields to keep the saved form compact and so a clamp
        # without a min doesn't serialize "min": null which is a bit ugly.
        out: Dict[str, Any] = {"path": self.path, "mode": self.mode}
        if self.max is not None:
            out["max"] = self.max
        if self.min is not None:
            out["min"] = self.min
        return out

    @staticmethod
    def from_dict(d: Dict[str, Any]) -> "ClampSpec":
        return ClampSpec(
            path=d["path"],
            max=d.get("max"),
            min=d.get("min"),
            mode=d.get("mode", "soft"),
        )


def _resolve_clamp_bound(bound: Any, entity_vars: Dict[str, Any]) -> Optional[float]:
    """Resolve a clamp bound to a numeric value, or None for "no bound."

    Numeric literal → returns as-is.
    String path → looks up in entity_vars, returns numeric value or None
                  if the path is missing or resolves to a non-numeric value.
    None / unknown type → None.
    """
    if bound is None:
        return None
    if isinstance(bound, bool):
        return None  # bools aren't valid bounds (caught at config time too)
    if isinstance(bound, (int, float)):
        return bound
    if isinstance(bound, str):
        # Resolve as a dotted path on entity vars
        cur: Any = entity_vars
        for seg in bound.split("."):
            if not isinstance(cur, dict) or seg not in cur:
                return None  # missing → no bound
            cur = cur[seg]
        if isinstance(cur, bool):
            return None  # value isn't numeric (semantically)
        if isinstance(cur, (int, float)):
            return cur
        return None  # non-numeric → no bound
    return None


def _apply_clamp(
    spec: ClampSpec,
    old_value: Any,
    new_value: Any,
    entity_vars: Dict[str, Any],
) -> Tuple[Any, bool]:
    """Apply a clamp to a numeric write. Returns (final_value, was_clamped).

    See module-level docstring for soft/hard semantics. If new_value isn't
    numeric (or is a bool), the value passes through unchanged with
    was_clamped=False.

    For soft clamps, "crossing from the legal side" is determined by checking
    whether old_value was within bounds. _MISSING (no prior value, i.e. a
    creation event) is treated as "crossing from below/above" — soft engages
    on initial writes that land outside the bounds. This matches the user
    intuition that creating a var with an out-of-range initial value should
    still respect the configured clamp.
    """
    # Non-numeric values bypass clamping entirely
    if isinstance(new_value, bool) or not isinstance(new_value, (int, float)):
        return new_value, False

    final = new_value
    clamped = False

    # --- max bound ---
    max_v = _resolve_clamp_bound(spec.max, entity_vars)
    if max_v is not None and new_value > max_v:
        if spec.mode == "hard":
            final = max_v
            clamped = True
        else:  # soft
            # Engage only if old_value was on the legal side (≤ max_v) or
            # didn't exist. _MISSING counts as "from below."
            was_legal = (
                old_value is _MISSING
                or isinstance(old_value, bool)
                or not isinstance(old_value, (int, float))
                or old_value <= max_v
            )
            if was_legal:
                final = max_v
                clamped = True

    # --- min bound (checked against `final`, not original new_value, so a
    #     max-clamp that lands above min doesn't trigger min-clamp spuriously) ---
    min_v = _resolve_clamp_bound(spec.min, entity_vars)
    if min_v is not None and final < min_v:
        if spec.mode == "hard":
            final = min_v
            clamped = True
        else:  # soft
            was_legal = (
                old_value is _MISSING
                or isinstance(old_value, bool)
                or not isinstance(old_value, (int, float))
                or old_value >= min_v
            )
            if was_legal:
                final = min_v
                clamped = True

    return final, clamped


# ============================================================================
# Var-event infrastructure
# ============================================================================
# A "var event" describes one observable change to entity.vars. Every write
# (via Entity.write_var) and every removal (via Entity.remove_var) produces
# a list of these events by diffing the old and new state of the affected
# subtree. The events are then fired as passive hooks.
#
# Why a separate VarEvent class rather than firing per-write inline:
#   1. A single user-visible write may produce many events. Writing
#      inventory.gold.coins=50 from an empty entity produces three creation
#      events (inventory, inventory.gold, inventory.gold.coins) plus three
#      on_var_written events.
#   2. The diff is computed once and the events are then materialized.
#      Keeping events as data lets us order them (top-down for created,
#      bottom-up for removed) before firing.
#   3. Tests can inspect the event list without hooking into the firing path.
# ============================================================================

@dataclass
class VarEvent:
    """A single observable change to entity.vars from one write or removal.

    Fields:
      kind             "created", "changed", or "removed" (never "written" — the
                       on_var_written catch-all subscribes to all three).
      key              dotted path that changed (e.g. "inventory.sword.damage").
      old_value        previous value at this path. None for "created". For
                       "removed" on a subtree, this carries the full removed
                       subtree as a (deep-copied) dict.
      new_value        new value at this path. None for "removed". This is
                       the value ACTUALLY stored — i.e. post-clamp if a clamp
                       engaged. Use `intended_value` to see what the caller
                       originally requested.
      intended_value   the value the caller passed to write_var before any
                       clamping. Equal to new_value when no clamp engaged.
                       None for "removed" events (the user intended absence,
                       not a value). Useful for overheal/overdamage tracking:
                       `intended_value - new_value` is the lost magnitude.
      was_clamped      True iff new_value differs from intended_value because
                       a clamp engaged on this write. False otherwise
                       (including bypass cases — a bypassed write didn't
                       clamp, even if the value would have been out of range).
    """
    kind: str       # "created" | "changed" | "removed"
    key: str
    old_value: Any
    new_value: Any
    intended_value: Any = None
    was_clamped: bool = False

    def __post_init__(self):
        # If the caller didn't explicitly set intended_value, mirror new_value
        # for create/change events (no clamping happened on this event), and
        # leave it as None for removal events (the caller intended absence).
        # write_var will override these for events where a clamp actually
        # engaged. We use a sentinel-style check rather than = field(default=
        # MISSING) to keep the dataclass declaration readable.
        if self.intended_value is None and self.kind != "removed":
            # For create/change we default intended_value to the actual new_value.
            # This means the common no-clamp case produces sensible event data
            # without every diff-side construction site having to set it.
            self.intended_value = self.new_value


def _deepcopy_value(v: Any) -> Any:
    """Deep-copy a value for safe inclusion in a VarEvent's old_value.

    We deep-copy old subtrees on removal events because the underlying dict
    has already been mutated by the time a passive observes the event — if
    the event held a reference into the old structure, a passive inspecting
    old_value would either see the post-mutation state or, worse, get a
    KeyError. Deep-copying decouples event data from current vars state.

    Only dicts/lists/tuples need deep-copying; scalars are immutable. We
    avoid importing copy.deepcopy because vars are expected to be plain
    JSON-like trees (dicts, lists, scalars) and a hand-rolled walk is both
    faster and won't choke on a stray non-pickleable object.
    """
    if isinstance(v, dict):
        return {k: _deepcopy_value(sub) for k, sub in v.items()}
    if isinstance(v, list):
        return [_deepcopy_value(sub) for sub in v]
    if isinstance(v, tuple):
        return tuple(_deepcopy_value(sub) for sub in v)
    return v  # scalar — immutable, safe to share


# Sentinel used internally to mean "no prior value at this path." We use a
# unique object rather than None because None can be a legitimate stored
# value (a formula could write `entity[hero].something = None`). Distinguishing
# "absent" from "set to None" matters for getting the created/changed split
# right.
_MISSING = object()


def _walk_subtree_keys(prefix: str, value: Any) -> List[Tuple[str, Any]]:
    """Enumerate every (dotted_key, value) pair in a subtree, including the
    root itself. Used when a whole new subtree is created or a whole subtree
    is removed: we need an event at every level inside, not just the root.

    Walk order is top-down (parent before children). The caller can reverse
    for bottom-up (removal) ordering.

    Non-dict values (scalars, lists) are leaves — we emit a single entry for
    them and don't recurse inside lists. (Lists of dicts are valid var
    content but list contents aren't subject to per-element hooks; a passive
    watching the list as a whole catches changes to it.)
    """
    out: List[Tuple[str, Any]] = [(prefix, value)]
    if isinstance(value, dict):
        for k, sub in value.items():
            sub_path = f"{prefix}.{k}" if prefix else k
            out.extend(_walk_subtree_keys(sub_path, sub))
    return out


def _diff_subtree(prefix: str, old: Any, new: Any) -> List[VarEvent]:
    """Compute the list of VarEvents that describes the transition from `old`
    to `new` at the given `prefix` path. The returned list is in a stable
    order suitable for firing as-is: creations come top-down, removals
    bottom-up, changes wherever they fall.

    Cases:
      - old is _MISSING and new is not: every (key, value) pair in the new
        subtree is a creation event, top-down.
      - old is not _MISSING and new is _MISSING: every (key, value) pair in
        the old subtree is a removal event, bottom-up. old_value for the
        root carries the whole removed subtree (deep-copied).
      - both are dicts: recurse — diff each key. Keys present in old but not
        new are removals; keys in new but not old are creations; keys in both
        are recursed-into (if either side is a dict) or directly compared
        (if both are scalars).
      - one is a dict and the other isn't (or scalar mismatch): treat the
        whole prefix as one change event. We don't emit per-leaf events for
        such a structural shift because the user replaced the whole node;
        there's no meaningful "old leaf at this path" to diff against.
      - both are scalars and equal: no event.
      - both are scalars and unequal: a single change event.
    """
    # Removal of a whole subtree
    if new is _MISSING:
        # Bottom-up: walk old, then reverse so leaves come first.
        pairs = _walk_subtree_keys(prefix, old)
        events: List[VarEvent] = []
        # For each level, old_value is the (deep-copied) subtree at that
        # level so passives can inspect what was lost. new_value is None.
        for key, val in reversed(pairs):
            events.append(VarEvent(
                kind="removed", key=key,
                old_value=_deepcopy_value(val), new_value=None,
            ))
        return events

    # Creation of a whole subtree
    if old is _MISSING:
        pairs = _walk_subtree_keys(prefix, new)
        events = []
        # Top-down: parents emitted first, then children.
        for key, val in pairs:
            events.append(VarEvent(
                kind="created", key=key, old_value=None, new_value=val,
            ))
        return events

    # Both present — diff their contents
    if isinstance(old, dict) and isinstance(new, dict):
        events = []
        old_keys = set(old.keys())
        new_keys = set(new.keys())
        # Creations first (top-down at this level; recursive walks inside
        # the subtree below will preserve top-down for nested creations).
        for k in new_keys - old_keys:
            sub_path = f"{prefix}.{k}" if prefix else k
            events.extend(_diff_subtree(sub_path, _MISSING, new[k]))
        # In-place changes for keys in both
        for k in old_keys & new_keys:
            sub_path = f"{prefix}.{k}" if prefix else k
            events.extend(_diff_subtree(sub_path, old[k], new[k]))
        # Removals last (each removal sequence is internally bottom-up)
        for k in old_keys - new_keys:
            sub_path = f"{prefix}.{k}" if prefix else k
            events.extend(_diff_subtree(sub_path, old[k], _MISSING))
        return events

    # Structural mismatch (e.g. dict <-> scalar) or scalar inequality
    # (types included: 1 -> true is a change, J17)
    if not same_value(old, new):
        return [VarEvent(
            kind="changed", key=prefix,
            old_value=_deepcopy_value(old), new_value=new,
        )]
    return []


def _path_resolve(root: Any, path: str) -> Any:
    """Resolve a dotted path through a nested dict. Returns _MISSING if any
    segment is absent or descends through a non-dict. Used to capture the
    'before' value at a write site for diffing."""
    if path == "":
        return root
    cur: Any = root
    for seg in path.split("."):
        if not isinstance(cur, dict) or seg not in cur:
            return _MISSING
        cur = cur[seg]
    return cur


def hook_output(m: Optional["Match"], kind: str, line: str) -> List[str]:
    """The lines a hook's run prints under the hook_output_lines rule
    (#215): kind `fired` (no result) shows under `all`, `result` under `all`
    and `with_result`, `error` always (under `none` as a private line,
    Match.private_lines)."""
    mode = str((m.rules if m is not None else {}).get(
        "hook_output_lines", "all"))
    if kind == "error":
        if mode == "none" and m is not None:
            return m.private_lines([line])
        return [line]
    if kind == "result":
        return [line] if mode in ("all", "with_result") else []
    return [line] if mode == "all" else []


def _run_passive_safely(engine, p: "Passive", ctx, *, target_id: str,
                        is_global: bool, label: Optional[str] = None
                        ) -> List[str]:
    """
    Run a single passive's formula and return its log lines (a fired line,
    a result or an error, as hook_output_lines lets them show). Catches
    FormulaError (and any other exception, defensively) so one broken
    passive can't cripple the whole hook fire.
    """
    m = getattr(engine, "_match", None)
    return hook_output(m, *_run_passive_line(engine, p, ctx,
                                             target_id=target_id,
                                             is_global=is_global,
                                             label=label))


def _run_passive_line(engine, p: "Passive", ctx, *, target_id: str,
                      is_global: bool, label: Optional[str] = None
                      ) -> Tuple[str, str]:
    """(kind, line) of one passive's run, for hook_output."""
    # Lazy import to avoid logic <-> formula import cycle.
    from formula import FormulaError
    given = label
    label = f"global passive `{p.id}`" if is_global else f"passive `{target_id}.{p.id}`"
    if given is not None:
        label = given
    elif is_global:
        # The fire sites pass is_global for everything _ordered_passives
        # yields, which includes TEAM passives — so a team passive used to be
        # logged as "global passive `regen`", sending a GM to `!gpassive
        # list` where it isn't. Name the table it actually lives in.
        m = getattr(engine, "_match", None)
        if m is not None and m.global_passives.get(p.id) is not p:
            for team, tps in (getattr(m, "team_passives", None) or {}).items():
                if tps.get(p.id) is p:
                    label = f"team passive `{team}.{p.id}`"
                    break
    try:
        result = engine.eval_program(p.formula, ctx)
        if result is None:
            return "fired", f"⚙️ {label} fired on `{target_id}` ({p.when})"
        return ("result",
                f"⚙️ {label} fired on `{target_id}` ({p.when}) → {result!r}")
    except FormulaError as ex:
        return "error", f"⚠️ {label} on `{target_id}` ({p.when}) FAILED: {ex}"
    except RecursionError:
        # Hooks that keep setting each other off past what Python's stack
        # holds (a var_hook_recursion_limit raised past ~90 levels): the
        # chain stops here, as at the limit; no crash entry, nothing broke.
        return "error", (
            f"⚠️ {label} on `{target_id}` ({p.when}) stopped: hooks set "
            f"each other off too deep (lower var_hook_recursion_limit).")
    except Exception as ex:
        # Defensive: programmer-error or unexpected bug shouldn't nuke a turn.
        ref = crash_ref(f"{label} on `{target_id}` ({p.when})", ex)
        return "error", (
            f"💥 {label} on `{target_id}` ({p.when}) CRASHED{ref}: "
            f"{type(ex).__name__}: {ex}")


# -------------------------
# SpecialTileTemplate (reusable tile definition: data defaults + hooks)
# -------------------------
# A template defines a KIND of special tile (e.g. "flame", "spike",
# "treasure_chest") that the GM can instantiate at any number of
# coordinates. Templates have:
#   - data:  dict of default field values copied into the tile dict at
#            placement time. Each placed instance carries its own copy
#            so edits on one instance don't propagate to others.
#   - hooks: dict[when, formula_src] of formulas that fire when an
#            entity transits any instance of this template. Looked up
#            LIVE every fire — editing template hooks immediately
#            affects all placed instances. The two halves intentionally
#            differ: data is instance state (drifts), hooks are shared
#            behavior (canonical).
#
# Unique one-off tiles ("a treasure chest at (5,5) with custom loot")
# don't need a template — they're written as ad-hoc instances via
# !tile set + !tile hook add, which keep working unchanged. Templates
# exist purely as a reuse convenience for tile KINDS that recur.
TILE_RESERVED_KEYS = frozenset({"_template", "hooks", "corpses"})
_CORPSES_RESERVED = ("`corpses` in tile data is where the engine keeps the "
                     "dead lying there: it can't be set or deleted as tile "
                     "data.")
# Keys in a tile dict that aren't user data:
#   _template — name of the template this instance was placed from
#               (absent on ad-hoc instances)
#   hooks     — per-instance hook overrides (override the template's
#               hooks per-when; primarily the !tile hook surface)
# Template definitions must not carry these names in their data dict;
# !tile def data rejects writes to either key.


def normalize_tags(raw: Any) -> List[str]:
    """A tag list in its stored shape: one-word strings, each once, in the
    order given. A text value is split on commas and spaces (`!zone tags z
    fire, poison`); anything else that isn't a list reads as no tags."""
    if isinstance(raw, str):
        raw = raw.replace(",", " ").split()
    if not isinstance(raw, list):
        return []
    out: List[str] = []
    for t in raw:
        if isinstance(t, str):
            t = t.strip()
            if t and not any(c.isspace() for c in t) and "," not in t \
                    and t not in out:
                out.append(t)
    return out


def check_tag(tag: Any) -> str:
    """`tag` when it can be a tag (one word: no spaces, commas,
    parentheses, brackets or double quotes, and not `and` / `or` / `not`,
    which tag filters read as words of an expression), else a VTTError.
    (`!ent set_var a tags ["fire"]` stored the one tag `[fire]`.)"""
    if not isinstance(tag, str) or not tag.strip() or \
            any(c.isspace() for c in tag.strip()) or \
            any(c in tag for c in ',()[]"'):
        raise VTTError(f"`{tag}` can't be a tag: one word, no spaces, "
                       f"commas, parentheses, brackets or double quotes "
                       f"(several tags: `fire,ice`).")
    if tag.strip() in TAG_FILTER_WORDS:
        raise VTTError(f"`{tag}` can't be a tag: and / or / not join the "
                       f"words of a tag filter.")
    return tag.strip()


# Tags (docs/tags_design.md). A tag FILTER is a list ("any of": a list, or
# comma / space text) or an EXPRESSION (`animal and not (undead or
# construct)`: `not` binds tightest, then `and`, then `or`). Text holding one
# of these words or a parenthesis is an expression.
TAG_FILTER_WORDS = ("and", "or", "not")
# Tags the engine derives from a unit's state; no tags var, grant or
# vocabulary entry can hold one.
ENGINE_TAGS = ("corpse", "part", "segment", "rider", "vehicle", "map_carrier")
# The key, in a status definition / instance, a var container or team data,
# whose tags the unit holding it carries.
GRANTS_UNIT_TAGS = "grants_unit_tags"
# The status definition field: a tag filter; the status can't be applied to
# a unit whose tags match it (fear on `mindless`).
STATUS_UNIT_TAG_BLOCK = "cannot_affect_units_with_tag"
_TAG_TOKEN_RE = re.compile(r"\(|\)|[^\s()]+")

# The tag vocabulary (docs/tags_design.md §7): a system's `tag_vocabulary`
# library names its tags; under `tag_vocabulary_mode` warn, a command that
# stores a tag the vocabulary lacks ends with a ⚠️. The keys whose values
# hold tags or tag filters wherever they sit (unit vars and containers,
# team data, status definitions, zone / tile data); the status token keys
# hold `tag:<filter>` tokens beside status names.
TAG_FIELD_KEYS = frozenset({
    "tags", "inner_tags", "exclude_inherited_tags", "action_tags",
    "exclude_inherited_action_tags", GRANTS_UNIT_TAGS, "not_tags",
    "target_requires_tags", "target_refuses_tags",
    "forbids_actions_with_tag", "immune_to_actions_with_tag",
    STATUS_UNIT_TAG_BLOCK})
_TAG_TOKEN_KEYS = frozenset({"removes", "blocked_by", "status_immune",
                             "__status_immune"})
# The tags a running top-level command stored that weren't there before,
# per the system whose vocabulary judges them (None = the command's own:
# the channel's match's system, else the server's default). Set by
# CommandRegistry._run_top only while a system of the server warns.
STORED_TAGS: "contextvars.ContextVar[Optional[Dict[Optional[str], Set[str]]]]" = (
    contextvars.ContextVar("vtt_stored_tags", default=None))


def _field_tag_words(value: Any, key: str) -> Set[str]:
    """The tags named in one tag field's value (a list, comma / space text
    or a filter expression; for a token key only its `tag:` tokens)."""
    items = value if isinstance(value, list) else [value]
    out: Set[str] = set()
    for item in items:
        if not isinstance(item, str):
            continue
        if key in _TAG_TOKEN_KEYS:
            depth, cur, toks = 0, "", []
            for ch in item:
                depth += (ch == "(") - (ch == ")")
                if ch == "," and depth == 0:
                    toks.append(cur)
                    cur = ""
                else:
                    cur += ch
            toks.append(cur)
            text = " ".join(t.strip()[4:] for t in toks
                            if t.strip().startswith("tag:"))
        else:
            text = item
        for w in _TAG_TOKEN_RE.findall(text.replace(",", " ")):
            if w in ("(", ")") or w in TAG_FILTER_WORDS or w in ("all", "*"):
                continue
            try:
                out.add(check_tag(w))
            except VTTError:
                pass
    return out


def tag_words(node: Any, key: Optional[str] = None,
              extra_keys: Iterable[str] = ()) -> Set[str]:
    """Every tag a stored value names: under `key` (the field the value is
    stored at) or, walking dicts and lists, under any TAG_FIELD_KEYS key
    (plus `extra_keys`, e.g. a renamed tags var). Engine tags are left out:
    the engine declares them."""
    keys = TAG_FIELD_KEYS | frozenset(extra_keys)
    out: Set[str] = set()

    def walk(n: Any, k: Optional[str], depth: int) -> None:
        if depth > STORE_DEPTH_LIMIT:
            return
        if k is not None and (k in keys or k in _TAG_TOKEN_KEYS) \
                and not isinstance(n, dict):
            out.update(_field_tag_words(n, k))
            return
        if isinstance(n, dict):
            for ck, cv in n.items():
                walk(cv, str(ck), depth + 1)
        elif isinstance(n, list):
            for cv in n:
                if isinstance(cv, (dict, list)):
                    walk(cv, None, depth + 1)
    walk(node, key, 0)
    return {t for t in out if t not in ENGINE_TAGS}


def written_tag_words(old: Any, new: Any, key: Optional[str] = None,
                      extra_keys: Iterable[str] = ()) -> Set[str]:
    """The tags of every tag field `new` writes over `old` (a field whose
    value changed counts all its tags; an unchanged one none). Engine tags
    are left out."""
    keys = TAG_FIELD_KEYS | frozenset(extra_keys)
    out: Set[str] = set()

    def walk(o: Any, n: Any, k: Optional[str], depth: int) -> None:
        if depth > STORE_DEPTH_LIMIT or o == n:
            return
        if k is not None and (k in keys or k in _TAG_TOKEN_KEYS) \
                and not isinstance(n, dict):
            out.update(_field_tag_words(n, k))
        elif isinstance(n, dict):
            for ck, cv in n.items():
                walk(o.get(ck) if isinstance(o, dict) else None, cv,
                     str(ck), depth + 1)
        elif isinstance(n, list):
            out.update(tag_words(n, None, extra_keys))
    walk(old, new, key, 0)
    return {t for t in out if t not in ENGINE_TAGS}


def note_stored_tags(system: Optional[str], old: Any, new: Any,
                     key: Optional[str] = None,
                     extra_keys: Iterable[str] = ()) -> None:
    """Record, for the running command, the tags of the tag fields `new`
    writes over `old` (at the field `key`), judged by `system`'s
    vocabulary. Nothing while no system of the server warns."""
    log = STORED_TAGS.get()
    if log is None:
        return
    words = written_tag_words(old, new, key, extra_keys)
    if words:
        log.setdefault(system, set()).update(words)


def _is_tag_expression(text: str) -> bool:
    return "(" in text or ")" in text or any(
        w in TAG_FILTER_WORDS for w in text.replace(",", " ").split())


# A tag expression's bounds: parentheses and `not`s nested at most this
# deep, at most this many words and parentheses. Parsing and matching
# recurse per nesting level, and a filter is text a player types (`!find
# tag:`) or stores in a var; 400 parentheses reached Python's stack limit.
TAG_EXPRESSION_DEPTH = 32
TAG_EXPRESSION_TOKENS = 256


@functools.lru_cache(maxsize=512)
def _parse_tag_expression(text: str) -> Tuple[Any, ...]:
    """The tree of a tag expression: ('tag', t), ('not', a), ('and', [a,
    b, ...]), ('or', [a, b, ...]) (a chain is one flat node, so only
    nesting deepens it). VTTError when it doesn't parse or passes the
    TAG_EXPRESSION_* bounds."""
    toks = _TAG_TOKEN_RE.findall(text)
    pos = 0
    depth = 0

    def bad(why: str) -> VTTError:
        shown = text if len(text) <= 80 else text[:77] + "..."
        return VTTError(f"Tag filter `{shown}`: {why}.")

    if len(toks) > TAG_EXPRESSION_TOKENS:
        raise bad(f"over {TAG_EXPRESSION_TOKENS} words and parentheses")

    def peek() -> Optional[str]:
        return toks[pos] if pos < len(toks) else None

    def take() -> str:
        nonlocal pos
        pos += 1
        return toks[pos - 1]

    def deeper() -> None:
        nonlocal depth
        depth += 1
        if depth > TAG_EXPRESSION_DEPTH:
            raise bad(f"parentheses and `not`s nest over "
                      f"{TAG_EXPRESSION_DEPTH} deep")

    def p_or() -> Tuple[Any, ...]:
        items = [p_and()]
        while peek() == "or":
            take()
            items.append(p_and())
        return items[0] if len(items) == 1 else ("or", items)

    def p_and() -> Tuple[Any, ...]:
        items = [p_not()]
        while peek() == "and":
            take()
            items.append(p_not())
        return items[0] if len(items) == 1 else ("and", items)

    def p_not() -> Tuple[Any, ...]:
        nonlocal depth
        if peek() == "not":
            take()
            deeper()
            inner = p_not()
            depth -= 1
            return ("not", inner)
        return p_atom()

    def p_atom() -> Tuple[Any, ...]:
        nonlocal depth
        t = peek()
        if t is None:
            raise bad("it ends where a tag or `(` should come")
        if t == "(":
            take()
            deeper()
            inner = p_or()
            if peek() != ")":
                raise bad("a `(` is never closed")
            take()
            depth -= 1
            return inner
        if t in (")", "and", "or"):
            raise bad(f"`{t}` where a tag should come")
        take()
        if "," in t:
            raise bad("commas list tags; inside an expression join them "
                      "with `or`")
        return ("tag", t)

    if not toks:
        raise bad("it's empty")
    tree = p_or()
    if pos < len(toks):
        raise bad(f"`{toks[pos]}` after the end of the expression")
    return tree


def _eval_tag_tree(tree: Tuple[Any, ...], tags: Set[str]) -> bool:
    op = tree[0]
    if op == "tag":
        return tree[1] in tags
    if op == "not":
        return not _eval_tag_tree(tree[1], tags)
    if op == "and":
        return all(_eval_tag_tree(t, tags) for t in tree[1])
    return any(_eval_tag_tree(t, tags) for t in tree[1])


def tag_filter_empty(raw: Any) -> bool:
    """Whether a tag filter field holds nothing (no requirement)."""
    if raw is None:
        return True
    if isinstance(raw, str):
        return not raw.strip()
    return isinstance(raw, list) and not raw


def check_tag_filter(raw: Any) -> Any:
    """A tag filter in its stored shape: a list of tags, or an expression's
    text. VTTError when it is neither (a word that can't be a tag, an
    expression that doesn't parse)."""
    if isinstance(raw, str) and _is_tag_expression(raw):
        _parse_tag_expression(raw.strip())
        return raw.strip()
    if isinstance(raw, str):
        raw = raw.replace(",", " ").split()
    if not isinstance(raw, list):
        raise VTTError(f"A tag filter is a list of tags or an expression, "
                       f"got {raw!r}.")
    out: List[str] = []
    for t in raw:
        t = check_tag(t)
        if t not in out:
            out.append(t)
    return out


# The key a watcher bundle sits under: a unit's own var, a container under
# its watcher_sources roots, a status, team data (Match.held_watchers).
WATCHERS_KEY = "watchers"


# The fields that define a match watcher (the rest is its edge state).
WATCHER_DEF_FIELDS = ("condition", "effect", "once", "once_each", "each",
                      "tag")


def watcher_definition(w: Dict[str, Any]) -> Dict[str, Any]:
    """A match watcher's (or a system library entry's) definition without
    its edge state: condition and effect as text, the flags only when set,
    `tag` when given."""
    out: Dict[str, Any] = {"condition": str(w.get("condition") or ""),
                           "effect": str(w.get("effect") or "")}
    for k in ("once", "once_each", "each"):
        if w.get(k):
            out[k] = True
    if w.get("tag") not in (None, ""):
        out["tag"] = copy.deepcopy(w["tag"])
    return out


def watcher_add_args(d: Dict[str, Any]) -> Dict[str, Any]:
    """Match.add_watcher's keyword arguments for definition `d`."""
    d = watcher_definition(d)
    return {"condition": d["condition"], "effect": d["effect"],
            "once": bool(d.get("once")), "once_each": bool(d.get("once_each")),
            "each": bool(d.get("each")), "tag": d.get("tag")}


def watcher_spec_problem(spec: Any) -> Optional[str]:
    """Why a held watcher entry can't be read, or None: a dict with a
    `condition` (text), an optional `effect` (text) and `once` (bool)."""
    if not isinstance(spec, dict):
        return "isn't a dict {condition, effect, once}"
    cond = spec.get("condition")
    if not isinstance(cond, str) or not cond.strip():
        return "has no `condition`"
    if not isinstance(spec.get("effect", ""), str):
        return "`effect` isn't a formula text"
    if not isinstance(spec.get("once", False), bool):
        return "`once` isn't true / false"
    return None


def tag_filter_matches(tags: Any, raw: Any) -> bool:
    """Whether the tags `tags` match the filter `raw` (a list: any of them;
    an expression). VTTError for a filter that doesn't parse."""
    have = set(tags) if not isinstance(tags, str) else {tags}
    if isinstance(raw, str) and _is_tag_expression(raw):
        return _eval_tag_tree(_parse_tag_expression(raw.strip()), have)
    return any(t in have for t in check_tag_filter(raw))


def checked_tag_list(raw: Any, where: str,
                     engine_ok: bool = False) -> List[str]:
    """A list of tags a unit carries or grants (its tags var, a
    grants_unit_tags value): a list or comma / space text of tags, none of
    them an engine tag (`engine_ok` for tags no unit carries: a team's, a
    map's). VTTError naming `where` otherwise."""
    if isinstance(raw, str):
        raw = raw.replace(",", " ").split()
    if not isinstance(raw, list):
        raise VTTError(f"{where}: a list of tags, got {raw!r}.")
    out: List[str] = []
    for t in raw:
        try:
            t = check_tag(t)
        except VTTError as ex:
            raise VTTError(f"{where}: {ex}")
        if t in ENGINE_TAGS and not engine_ok:
            raise VTTError(
                f"{where}: `{t}` is an engine tag ({', '.join(ENGINE_TAGS)}): "
                f"the engine gives it from the unit's state.")
        if t not in out:
            out.append(t)
    return out


def checked_tag_vars(path: str, value: Any, tags_var: str,
                     where: str) -> Any:
    """`value` about to be written at the unit var `path`, with its tag
    fields checked and normalized: the tags var itself (top level, nothing
    under it) and every `grants_unit_tags` key at or under the path."""
    segs = path.split(".") if path else []
    if segs and segs[0] == tags_var:
        if len(segs) > 1:
            raise VTTError(f"{where}: the tags var `{tags_var}` is one list; "
                           f"nothing nests under it.")
        return checked_tag_list(value, f"{where}: `{tags_var}`")
    if GRANTS_UNIT_TAGS in segs:
        if segs[-1] != GRANTS_UNIT_TAGS:
            raise VTTError(f"{where}: `{GRANTS_UNIT_TAGS}` is a list of "
                           f"tags; nothing nests under it.")
        return checked_tag_list(value, f"{where}: `{path}`")

    def walk(node: Any, at: str) -> None:
        if isinstance(node, dict):
            for k in list(node):
                sub = f"{at}.{k}" if at else str(k)
                if k == GRANTS_UNIT_TAGS:
                    node[k] = checked_tag_list(node[k], f"{where}: `{sub}`")
                else:
                    walk(node[k], sub)
    if isinstance(value, dict):
        if not segs:
            if tags_var in value:
                value[tags_var] = checked_tag_list(
                    value[tags_var], f"{where}: `{tags_var}`")
        walk(value, path)
    return value


@dataclass
class SpecialTileTemplate:
    name: str
    data: Dict[str, Any] = field(default_factory=dict)
    hooks: Dict[str, str] = field(default_factory=dict)
    # A template field (outside `data`, so placing a tile doesn't copy it):
    # a placed tile's tags are these, read live, plus its own `tags` data.
    tags: List[str] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        out = {
            "name": self.name,
            "data": copy.deepcopy(self.data),
            "hooks": dict(self.hooks),
        }
        if self.tags:
            out["tags"] = list(self.tags)
        return out

    @staticmethod
    def from_dict(d: Dict[str, Any]) -> "SpecialTileTemplate":
        return SpecialTileTemplate(
            name=str(d["name"]),
            # Only an object is tile data (a number there crashed every
            # reader of the template's look, S13).
            data=(copy.deepcopy(d["data"])
                  if isinstance(d.get("data"), dict) else {}),
            hooks={
                str(k): str(v)
                for k, v in (d["hooks"] if isinstance(d.get("hooks"), dict)
                             else {}).items()
                if isinstance(v, str)
            },
            tags=normalize_tags(d.get("tags")),
        )


# Zone DEFINITIONS describe a kind of zone once (`poison_cloud`), the way a
# tile template describes a kind of tile. A zone naming one (its `def`
# field) reads the definition's hooks, look fields (ZONE_LOOK_FIELDS) and
# tags LIVE, its own value winning; the definition's `data` and `facing` are
# copied into the zone when it is made (data read through for `block` /
# `opaque` when the zone's data lacks them, as a tile reads its template's;
# facing materialized like a unit's, user call). The tile-template
# pattern, so the two map features with definitions behave alike. Stored as
# plain dicts in Match.zone_definitions (and a system library), in the
# shape normalize_zone_def gives.
ZONE_LOOK_FIELDS: Tuple[str, ...] = ("glyph", "color", "sprite", "legend",
                                     "facing", "glyphs", "sprites")
# The per-facing look fields (#257) and the plain field each stands in for:
# `glyphs.<facing>` / `sprites.<facing>` on units, tiles (data, template
# data), zones and zone definitions.
FACING_LOOK_FIELDS: Dict[str, str] = {"glyphs": "glyph", "sprites": "sprite"}
# The tile data key / zone field holding a facing (#257).
FACING_FIELD = "facing"


def checked_facing_data(path: str, value: Any) -> Any:
    """`value` about to be stored at tile data `path`: a write at `facing`
    must name a direction (stored as its canonical name), and nothing
    nests under it. Other paths pass unchanged."""
    segs = str(path).split(".")
    if segs[0] != FACING_FIELD:
        return value
    if len(segs) > 1:
        raise VTTError("`facing` holds one direction; nothing nests under "
                       "it.")
    canon = normalize_direction(value) if isinstance(value, str) else None
    if canon is None:
        raise VTTError(f"`facing` must be a direction (up, down, left, "
                       f"right, or a diagonal), not {value!r}.")
    return canon


def facing_look_entry(kind: str, facing: Any, value: Any) -> bool:
    """Whether `value` is a usable `glyphs` / `sprites` entry for `facing`."""
    if not isinstance(facing, str) or facing not in ALLOWED_DIRECTIONS:
        return False
    if kind == "glyphs":
        return isinstance(value, str) and len(value) == 1
    return isinstance(value, str) and bool(value)


def zone_look_value(key: str, value: Any) -> bool:
    """Whether `value` is a usable zone look field `key` (a one-character
    glyph, a non-empty color / sprite text, a legend text or False, a
    direction, a {facing: glyph / sprite} dict with a usable entry)."""
    if key == "glyph":
        return isinstance(value, str) and len(value) == 1
    if key == "legend":
        return value is False or (isinstance(value, str) and bool(value))
    if key == "facing":
        return isinstance(value, str) and value in ALLOWED_DIRECTIONS
    if key in FACING_LOOK_FIELDS:
        return isinstance(value, dict) and any(
            facing_look_entry(key, f, v) for f, v in value.items())
    return isinstance(value, str) and bool(value)


def check_zone_def_name(name: Any) -> None:
    """Raise unless `name` can name a zone definition: id characters, as a
    zone name (a zone made from it takes its name)."""
    if not isinstance(name, str) or not ID_RE.fullmatch(name):
        raise VTTError(f"`{name}` can't be a zone definition name: letters, "
                       f"digits, `_` and `-` only (1-40 characters).")


def normalize_zone_def(raw: Any) -> Dict[str, Any]:
    """A zone definition in its stored shape: `data` (a dict), `hooks` (zone
    hook name -> formula text), `tags` (a list) and the look fields that are
    set. Malformed parts are dropped (a save from an older build loads)."""
    raw = raw if isinstance(raw, dict) else {}
    data = raw.get("data")
    hooks = raw.get("hooks")
    out: Dict[str, Any] = {
        "data": copy.deepcopy(data) if isinstance(data, dict) else {},
        "hooks": {k: v for k, v in hooks.items()
                  if isinstance(k, str) and isinstance(v, str) and v}
        if isinstance(hooks, dict) else {},
        "tags": normalize_tags(raw.get("tags")),
    }
    for key in ZONE_LOOK_FIELDS:
        if zone_look_value(key, raw.get(key)):
            out[key] = copy.deepcopy(raw[key])
    out.update(zone_grant_fields(raw))
    return out


# ---- status-granting zones (#136) ----------------------------------------
# A zone (or zone definition) may carry `grants` (status name -> {level,
# data, linger}), `grant_condition` (an expression, self = the unit, which
# must hold for the unit to receive the grants) and `grant_bodies` (root /
# all, else the zone_status_grant_bodies rule). Match.sync_zone_grants puts
# the statuses on the units inside and takes them off once no granting zone
# covers them. A granted status instance carries ZONE_GRANT_KEY (the zones
# holding it) and ZONE_LINGER_KEY (the turns it lingers once they all let
# go); a lingering one carries ZONE_LINGERING_KEY until a zone takes it
# back. A status a unit got some other way never carries the key, so a
# zone never takes it over or removes it.
ZONE_GRANT_FIELDS: Tuple[str, ...] = ("grants", "grant_condition",
                                      "grant_bodies")
ZONE_GRANT_BODIES = ("root", "all")
ZONE_GRANT_KEY = "__zone_grant"
ZONE_LINGER_KEY = "__zone_linger"
ZONE_LINGERING_KEY = "__zone_lingering"
# What the zones holding a granted status give it now ({level, data}: the
# highest level among them and that zone's data), so a later sync updates
# the instance when it changes (L40: a unit walking from a level-1 zone into
# a level-3 one, or a grant edit, reaches the units already inside).
ZONE_SPEC_KEY = "__zone_spec"
# Passes one sync makes at most when the status hooks it fires move units
# (each move asks for another pass).
ZONE_GRANT_PASSES = 8


def check_zone_grant(status: Any, entry: Any) -> Dict[str, Any]:
    """Grant `entry` for status `status` in its stored shape ({level, data,
    linger}, each only when set); raises VTTError on a malformed one."""
    check_status_name(status)
    if not isinstance(entry, dict):
        raise VTTError(f"grant `{status}` must be a dict of level / data / "
                       f"linger.")
    unknown = sorted(set(entry) - {"level", "data", "linger"})
    if unknown:
        raise VTTError(f"grant `{status}`: unknown field(s) "
                       f"{', '.join(unknown)} (level, data, linger).")
    out: Dict[str, Any] = {}
    for key in ("level", "linger"):
        v = entry.get(key)
        if v is None:
            continue
        if isinstance(v, bool) or not isinstance(v, (int, float)) \
                or v != v or v in (float("inf"), float("-inf")) \
                or int(v) != v:
            raise VTTError(f"grant `{status}`: {key} must be a whole number, "
                           f"not {v!r}.")
        if key == "linger" and v < 0:
            raise VTTError(f"grant `{status}`: linger can't be negative.")
        out[key] = int(v)
    data = entry.get("data")
    if data is not None:
        if not isinstance(data, dict):
            raise VTTError(f"grant `{status}`: data must be a dict.")
        bad = sorted(k for k in data if str(k) in (
            "level", ZONE_GRANT_KEY, ZONE_LINGER_KEY, ZONE_LINGERING_KEY,
            ZONE_SPEC_KEY))
        if bad:
            raise VTTError(f"grant `{status}`: data can't set "
                           f"{', '.join(bad)} (`level` is its own field).")
        for k, v in data.items():
            check_status_self_grant(status, str(k), v)
        if data:
            out["data"] = _own_value(data)
    return out


def without_zone_grants(status: Any) -> Any:
    """A unit dict's `status` without the statuses a zone holds (a lingering
    one stays: it is the unit's own now). Library saves and snapshots leave
    them out: the zone holds them, and it gives them back where it covers
    the unit."""
    if not isinstance(status, dict):
        return status
    return {k: v for k, v in status.items()
            if not (isinstance(v, dict) and ZONE_GRANT_KEY in v)}


def _dict_path_get(d: Any, path: str) -> Tuple[bool, Any]:
    """(found, value) at dotted `path` in nested dict `d`."""
    node = d
    for key in path.split("."):
        if not isinstance(node, dict) or key not in node:
            return False, None
        node = node[key]
    return True, node


def _dict_path_set(d: Dict[str, Any], path: str, value: Any) -> None:
    """Set dotted `path` in nested dict `d`, making the dicts on the way (a
    plain value in the way is replaced)."""
    keys = path.split(".")
    node = d
    for key in keys[:-1]:
        if not isinstance(node.get(key), dict):
            node[key] = {}
        node = node[key]
    node[keys[-1]] = value


def zone_grant_fields(raw: Any) -> Dict[str, Any]:
    """The usable #136 grant fields of zone / definition dict `raw`, in
    their stored shape; malformed ones are dropped (a file from an older
    build or edited by hand loads)."""
    out: Dict[str, Any] = {}
    if not isinstance(raw, dict):
        return out
    grants = raw.get("grants")
    if isinstance(grants, dict):
        kept = {}
        for sname, entry in grants.items():
            try:
                kept[sname] = check_zone_grant(sname, entry)
            except VTTError:
                continue
        if kept:
            out["grants"] = kept
    cond = raw.get("grant_condition")
    if isinstance(cond, str) and cond.strip():
        out["grant_condition"] = cond
    if raw.get("grant_bodies") in ZONE_GRANT_BODIES:
        out["grant_bodies"] = raw["grant_bodies"]
    return out


# -------------------------
# FormulaFunction (a reusable, user-defined formula callable)
# -------------------------
# A FormulaFunction is a named formula body plus a list of parameter
# names. Once defined on a match (via !func def), any formula can call
# it by name — `damage_after_armor(entity[self].atk, entity[target].def)`
# — and the body runs with the parameters bound as plain identifiers.
#
# The body is a full formula program: it may have statements (including
# entity[X] writes, which take effect as side effects) and an optional
# trailing expression whose value becomes the function's return value.
# A body with no trailing expression returns None.
#
# Inside the body:
#   - the parameter names are bound to the call's argument values
#   - entity[self] / entity[this] resolve against the CALLER's context
#     (functions are macros that run in the caller's frame, not a fresh
#     one) — so a function called from a passive sees that passive's
#     `self`
#   - other formula functions (and builtins) are callable, enabling
#     composition and recursion (bounded by the recursion limit rule)
#
# Compilation of the body is cached on the instance (the _compiled
# field, excluded from equality / repr / serialization). Redefining a
# function replaces the instance, so the cache is naturally fresh.
_FUNC_NAME_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


@dataclass
class FormulaFunction:
    name: str
    params: List[str] = field(default_factory=list)
    body: str = ""
    # Lazily-populated compiled artifact, set by the formula engine on
    # first call. Opaque to logic.py. Excluded from comparison/repr so
    # two functions with the same source are still equal, and from
    # to_dict so it never leaks into save files.
    _compiled: Any = field(default=None, compare=False, repr=False)

    def signature(self) -> str:
        """Human-readable `name(p1, p2)` for listings and errors."""
        return f"{self.name}({', '.join(self.params)})"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "name": self.name,
            "params": list(self.params),
            "body": self.body,
        }

    @staticmethod
    def from_dict(d: Dict[str, Any]) -> "FormulaFunction":
        return FormulaFunction(
            name=str(d["name"]),
            params=[str(p) for p in (d.get("params", []) or [])],
            body=str(d.get("body", "")),
        )


# Action built-ins and bindings a `!func` name would never reach.
_FORMULA_RESERVED_NAMES = frozenset({"cmd", "fail", "choose", "choose_number",
                                     "source", "args"})


def check_formula_function(name: Any, params: List[Any]) -> None:
    """Refuse a formula function name or parameter list that can't work:
    names must be identifiers that don't shadow a built-in, parameters
    unique identifiers that aren't built-ins, `entity` or `__`-prefixed.
    Shared by match functions (`!func def`) and system libraries
    (`!system func def`); the body is validated by the caller."""
    if not isinstance(name, str) or not _FUNC_NAME_RE.match(name):
        raise VTTError(
            f"formula function name '{name}' must be a valid "
            f"identifier (letters, digits, underscore; not starting "
            f"with a digit)."
        )
    # Lazy import to avoid a logic <-> formula import cycle at module
    # load. We only need the reserved-name set.
    from formula import (_ALLOWED_FUNCS, _MATCH_FUNC_NAMES,
                         HOOK_CONTEXT_NAMES, _ENTITY_TOKEN_NAMES)
    if name in _ALLOWED_FUNCS or name in _MATCH_FUNC_NAMES:
        raise VTTError(
            f"'{name}' is a built-in formula function and cannot be "
            f"redefined."
        )
    # A name the engine resolves first could never be called (`self`, a
    # hook binding, an action built-in), and a `__` name would replace one
    # of the engine's own helpers (`__read`, `__safe_add`) in every formula.
    if (name.startswith("__") or name == "entity" or keyword.iskeyword(name)
            or name in ("True", "False", "None", "true", "false", "none")
            or name in _ENTITY_TOKEN_NAMES or name in HOOK_CONTEXT_NAMES
            or name in _FORMULA_RESERVED_NAMES):
        raise VTTError(
            f"'{name}' is reserved by the formula engine; pick a different "
            f"name.")
    seen = set()
    for p in params:
        if not isinstance(p, str) or not _FUNC_NAME_RE.match(p):
            raise VTTError(
                f"parameter name '{p}' must be a valid identifier."
            )
        if p in seen:
            raise VTTError(f"duplicate parameter name '{p}'.")
        seen.add(p)
        if p in _ALLOWED_FUNCS or p in _MATCH_FUNC_NAMES:
            raise VTTError(
                f"parameter name '{p}' collides with a built-in "
                f"formula function; pick a different name."
            )
        # `entity` is the magic accessor keyword and __-prefixed
        # names are transformer-injected internals; a parameter
        # using either would either shadow the accessor or never be
        # reachable. Reject both up front.
        if p == "entity" or p.startswith("__") or p in (
                "true", "false", "none"):
            raise VTTError(
                f"parameter name '{p}' is reserved; pick a different "
                f"name."
            )


# -------------------------
# GameSystem (stores global rules for a game system, so not everything has to be manually set each match)
# -------------------------

# GameSystem inheritance (MatchManager.system_chain): the structured rules a
# child MERGES over its parent entry by entry (dict rules by key, list rules
# by the named field) instead of replacing whole, and the libraries a child
# inherits by name. A child's removals of inherited entries live in
# GameSystem.removed under the same names.
MERGE_RULES: Dict[str, Optional[str]] = {
    "command_access": None, "default_entity_vars": None,
    "default_map_vars": None,
    "event_log_format": None, "default_clamps": "path",
    "default_entity_passives": "id",
}
SYSTEM_LIBRARIES: Tuple[str, ...] = ("aliases", "tile_templates",
                                     "formula_functions",
                                     "status_definitions", "tables",
                                     "macros", "zone_definitions",
                                     "tag_vocabulary", "watchers",
                                     "var_labels")

